    fn staged_package(&self, preserve_unchanged_modelled_parts: bool) -> Result<OpcPackage> {
        #[cfg(all(feature = "render", test))]
        STAGED_PACKAGE_COUNT.with(|count| count.set(count.get() + 1));
        if self.core_properties_dirty
            && self
                .package
                .package_rels
                .get_by_type(rel_types::CORE_PROPERTIES)
                .is_none()
            && self.package.contains_part(&self.core_properties_part_name)
        {
            return Err(Error::CorePropertiesPartCollision {
                part_name: self.core_properties_part_name.clone(),
            });
        }
        let mut package = self.package.clone();
        self.media_store.write_new_parts(&mut package);
        if let Some(properties) = self
            .core_properties
            .as_ref()
            .filter(|_| self.core_properties_dirty)
        {
            let xml = properties.to_xml().map_err(|error| Error::MalformedPart {
                part_name: self.core_properties_part_name.clone(),
                message: error.to_string(),
            })?;
            package.set_part(&self.core_properties_part_name, xml);
            package.content_types.add_override(
                &self.core_properties_part_name,
                content_types::CORE_PROPERTIES,
            );
            if package
                .package_rels
                .get_by_type(rel_types::CORE_PROPERTIES)
                .is_none()
            {
                let target = self
                    .core_properties_part_name
                    .strip_prefix('/')
                    .unwrap_or(&self.core_properties_part_name);
                package.package_rels.add(rel_types::CORE_PROPERTIES, target);
            }
        }
        let presentation_changed = match self
            .parsed
            .as_deref()
            .and_then(|parsed| parsed.presentation(&self.package, &self.presentation_part))
        {
            Some(parsed) => *parsed != self.presentation,
            None => {
                self.package
                    .get_part(&self.presentation_part)
                    .and_then(|xml| CT_Presentation::from_xml(xml).ok())
                    .as_ref()
                    != Some(&self.presentation)
            }
        };
        if !preserve_unchanged_modelled_parts || presentation_changed {
            package.set_part(
                &self.presentation_part,
                self.presentation
                    .to_xml()
                    .map_err(|error| Error::MalformedPart {
                        part_name: self.presentation_part.clone(),
                        message: error.to_string(),
                    })?,
            );
        }
        if let Some(part_name) = self
            .comment_authors_part
            .as_ref()
            .filter(|_| self.comment_authors_dirty)
        {
            package.set_part(
                part_name,
                self.comment_authors
                    .to_xml()
                    .map_err(|error| Error::MalformedPart {
                        part_name: part_name.clone(),
                        message: error.to_string(),
                    })?,
            );
            package
                .content_types
                .add_override(part_name, content_types::POWERPOINT_AUTHORS);
        }
        if let (Some(part_name), Some(master)) = (
            self.notes_master_part
                .as_ref()
                .filter(|_| self.notes_master_dirty),
            &self.notes_master,
        ) {
            package.set_part(
                part_name,
                master.to_xml().map_err(|error| Error::MalformedPart {
                    part_name: part_name.clone(),
                    message: error.to_string(),
                })?,
            );
        }
        if let (Some(part_name), Some(master)) = (
            self.handout_master_part
                .as_ref()
                .filter(|_| self.handout_master_dirty),
            &self.handout_master,
        ) {
            package.set_part(
                part_name,
                master.to_xml().map_err(|error| Error::MalformedPart {
                    part_name: part_name.clone(),
                    message: error.to_string(),
                })?,
            );
        }
        for record in self.masters.iter().filter(|record| record.dirty) {
            let master = record
                .master
                .as_ref()
                .map_err(|message| Error::MalformedPart {
                    part_name: record.part_name.clone(),
                    message: message.clone(),
                })?;
            let original = self
                .package
                .get_part(&record.part_name)
                .and_then(|xml| CT_SlideMaster::from_xml(xml).ok());
            if original.as_ref() != Some(master) {
                package.set_part(
                    &record.part_name,
                    master.to_xml().map_err(|error| Error::MalformedPart {
                        part_name: record.part_name.clone(),
                        message: error.to_string(),
                    })?,
                );
            }
        }
        for record in self.layouts.iter().filter(|record| record.dirty) {
            let original = self
                .package
                .get_part(&record.part_name)
                .and_then(|xml| CT_SlideLayout::from_xml(xml).ok());
            if original.as_ref() != Some(&record.layout) {
                package.set_part(
                    &record.part_name,
                    record
                        .layout
                        .to_xml()
                        .map_err(|error| Error::MalformedPart {
                            part_name: record.part_name.clone(),
                            message: error.to_string(),
                        })?,
                );
            }
        }
        for record in self.themes.iter().filter(|record| record.dirty) {
            let original = self
                .package
                .get_part(&record.part_name)
                .and_then(|xml| CT_OfficeStyleSheet::from_xml(xml).ok());
            if original.as_ref() != Some(&record.theme) {
                package.set_part(
                    &record.part_name,
                    record
                        .theme
                        .to_xml()
                        .map_err(|error| Error::MalformedPart {
                            part_name: record.part_name.clone(),
                            message: error.to_string(),
                        })?,
                );
            }
        }
        for record in &self.slides {
            note_fx260_slide(1);
            // A record parsed from the bytes its parts still hold is unchanged
            // without parsing them again.
            let parsed = self
                .parsed
                .as_deref()
                .filter(|parsed| parsed.holds_slide(record));
            let parsed_from =
                |part: &str| parsed.is_some_and(|parsed| parsed.same_bytes(&self.package, part));
            let slide_changed = !parsed_from(&record.part_name) && {
                note_commit_work(|work| work.parsed += 1);
                self.package
                    .get_part(&record.part_name)
                    .and_then(|xml| CT_Slide::from_xml(xml).ok())
                    .as_ref()
                    != Some(&record.slide)
            };
            if !preserve_unchanged_modelled_parts || slide_changed {
                note_commit_work(|work| work.serialized += 1);
                package.set_part(
                    &record.part_name,
                    record
                        .slide
                        .to_xml()
                        .map_err(|error| Error::MalformedPart {
                            part_name: record.part_name.clone(),
                            message: error.to_string(),
                        })?,
                );
            }
            if let Some(notes) = &record.notes {
                let notes_changed = !parsed_from(&notes.part_name) && {
                    note_commit_work(|work| work.parsed += 1);
                    self.package
                        .get_part(&notes.part_name)
                        .and_then(|xml| CT_NotesSlide::from_xml(xml).ok())
                        .as_ref()
                        != Some(&notes.notes)
                };
                if !preserve_unchanged_modelled_parts || notes_changed {
                    note_commit_work(|work| work.serialized += 1);
                    package.set_part(
                        &notes.part_name,
                        notes.notes.to_xml().map_err(|error| Error::MalformedPart {
                            part_name: notes.part_name.clone(),
                            message: error.to_string(),
                        })?,
                    );
                }
            }
            if let Some(comments) = record.comments.as_ref().filter(|comments| comments.dirty) {
                package.set_part(
                    &comments.part_name,
                    comments
                        .comments
                        .to_xml()
                        .map_err(|error| Error::MalformedPart {
                            part_name: comments.part_name.clone(),
                            message: error.to_string(),
                        })?,
                );
                package
                    .content_types
                    .add_override(&comments.part_name, content_types::POWERPOINT_COMMENTS);
            }
        }
        Ok(package)
    }

    /// Saves the deterministic package bytes to a path.
    ///
    /// The bytes are staged in a synced sibling file and renamed over `path`
    /// through [`oxml_opc::write_atomic_file`], so a failed save leaves an
    /// existing file as it was. A symbolic link at `path` is kept and the file
    /// it names is replaced, and on Unix that file keeps its permission bits.
    ///
    /// A `.pptx`, `.pptm`, `.potx`, `.potm`, `.ppsx`, or `.ppsm` extension
    /// selects the main part content type, so a template saved as `.pptx`
    /// declares a presentation. Any other extension keeps the opened class,
    /// and `save_encrypted` ignores the extension. When the class changes, a
    /// presentation part that carries a VBA project
    /// cannot be saved under a macro-free extension, because the project
    /// would remain in a file that claims to carry none.
    /// [`Presentation::save_as_package_class`] performs that conversion
    /// explicitly and keeps the VBA part.
    pub fn save<P: AsRef<Path>>(&self, path: P) -> Result<()> {
        debug_assert!(
            self.save_invariants_preserved(),
            "invalid presentation at path save boundary: {:?}",
            self.validate()
        );
        write_atomic_file(
            path.as_ref(),
            &self.to_bytes_for_path(path.as_ref())?,
            "rpptx",
            "invalid PowerPoint package file name",
            "could not allocate PowerPoint package save staging file",
        )
        .map_err(OpcError::from)?;
        Ok(())
    }

    /// Saves a password-protected presentation through an atomic path publication.
    #[cfg(all(feature = "agile-encryption", not(target_arch = "wasm32")))]
    pub fn save_encrypted<P: AsRef<Path>>(&self, path: P, password: &str) -> Result<()> {
        let bytes = self.to_encrypted_bytes(password)?;
        write_atomic_file(
            path.as_ref(),
            &bytes,
            "rpptx",
            "invalid file name",
            "could not allocate encrypted-save staging file",
        )
        .map_err(OpcError::from)?;
        Ok(())
    }

    /// Saves a slideshow package without changing later ordinary saves.
    pub fn save_as_show<P: AsRef<Path>>(&self, path: P) -> Result<()> {
        self.save_as_package_class(path, PresentationPackageClass::Slideshow)
    }

    /// Saves an output copy with the selected modern package class.
    ///
    /// The file is replaced the way [`Presentation::save`] replaces it.
    pub fn save_as_package_class<P: AsRef<Path>>(
        &self,
        path: P,
        class: PresentationPackageClass,
    ) -> Result<()> {
        write_atomic_file(
            path.as_ref(),
            &self.to_bytes_as(class)?,
            "rpptx",
            "invalid PowerPoint package file name",
            "could not allocate PowerPoint package save staging file",
        )
        .map_err(OpcError::from)?;
        Ok(())
    }

    /// Returns every detected package and PresentationML invariant violation.
    pub fn validate(&self) -> Vec<ValidationIssue> {
        let mut duplicate_shape_ids = Vec::new();
        let mut out_of_range_slide_ids = Vec::new();
        let mut duplicate_slide_ids = Vec::new();
        let mut missing_content_types = Vec::new();
        let mut dangling_relationships = Vec::new();
        let mut unreachable_targets = Vec::new();
        let mut empty_text_bodies = Vec::new();
        let mut duplicate_placeholder_indices = Vec::new();
        let mut orphan_media = Vec::new();
        let mut custom_show_references = Vec::new();
        let mut missing_layout_relationships = Vec::new();
        let mut missing_theme_relationships = Vec::new();

        for (slide_index, record) in self.slides.iter().enumerate() {
            let mut shape_ids = record
                .slide
                .common_slide_data
                .shape_tree
                .non_visual_id()
                .into_iter()
                .collect();
            let mut placeholder_indices = HashSet::new();
            let mut shape_index = 0usize;
            validate_shape_children(
                slide_index,
                &record.slide.common_slide_data.shape_tree.children,
                &mut shape_index,
                &mut shape_ids,
                &mut placeholder_indices,
                &mut duplicate_shape_ids,
                &mut empty_text_bodies,
                &mut duplicate_placeholder_indices,
            );
        }

        let mut slide_ids = HashSet::new();
        for (slide_index, slide) in self.presentation.slide_ids.iter().enumerate() {
            if !(256..=2_147_483_647).contains(&slide.id) {
                out_of_range_slide_ids.push(ValidationIssue::SlideIdOutOfRange {
                    slide: slide_index,
                    id: slide.id,
                });
            }
            if !slide_ids.insert(slide.id) {
                duplicate_slide_ids.push(ValidationIssue::DuplicateSlideId { id: slide.id });
            }
        }

        let mut part_names = self.package.parts.keys().collect::<Vec<_>>();
        part_names.sort_unstable();
        for part_name in part_names {
            if !part_has_content_type(&self.package, part_name) {
                missing_content_types.push(ValidationIssue::MissingContentTypeOverride {
                    part: part_name.clone(),
                });
            }
        }

        let mut incoming_targets = HashSet::new();
        validate_relationship_scope(
            &self.package,
            "/",
            None,
            &self.package.package_rels,
            &mut incoming_targets,
            &mut dangling_relationships,
            &mut unreachable_targets,
        );
        let mut relationship_sources = self
            .package
            .parts
            .keys()
            .chain(self.package.part_rels.keys())
            .map(String::as_str)
            .collect::<Vec<_>>();
        relationship_sources.sort_unstable();
        relationship_sources.dedup();
        let empty_relationships = Relationships::new();
        for source_part in relationship_sources {
            let relationships = self
                .package
                .get_part_rels(source_part)
                .unwrap_or(&empty_relationships);
            let source_xml = self.current_part_xml(source_part);
            validate_relationship_scope(
                &self.package,
                source_part,
                source_xml.as_deref(),
                relationships,
                &mut incoming_targets,
                &mut dangling_relationships,
                &mut unreachable_targets,
            );
        }

        let mut media_parts = self
            .package
            .parts
            .keys()
            .filter(|part| part.to_ascii_lowercase().starts_with("/ppt/media/"))
            .collect::<Vec<_>>();
        media_parts.sort_unstable();
        for part in media_parts {
            if !incoming_targets.contains(&part.to_ascii_lowercase()) {
                orphan_media.push(ValidationIssue::OrphanMedia { part: part.clone() });
            }
        }

        let presentation_relationships = self.package.get_part_rels(&self.presentation_part);
        let slide_relationship_ids = self
            .presentation
            .slide_ids
            .iter()
            .map(|slide| slide.relationship_id.as_str())
            .collect::<HashSet<_>>();
        if let Some(xml) = self.current_part_xml(&self.presentation_part)
            && let Ok(references) = custom_show_relationship_ids(&xml)
        {
            for relationship_id in references {
                if !slide_relationship_ids.contains(relationship_id.as_str()) {
                    custom_show_references.push(ValidationIssue::CustomShowReference {
                        slide_id: numeric_relationship_id(&relationship_id),
                    });
                }
            }
        }

        for (slide_index, slide) in self.slides.iter().enumerate() {
            let count = self
                .package
                .get_part_rels(&slide.part_name)
                .map(|relationships| {
                    relationships
                        .items
                        .iter()
                        .filter(|relationship| {
                            relationship.rel_type == rel_types::SLIDE_LAYOUT
                                && !relationship_is_external(relationship)
                        })
                        .count()
                })
                .unwrap_or_default();
            if count != 1 {
                missing_layout_relationships
                    .push(ValidationIssue::MissingLayoutRel { slide: slide_index });
            }
        }

        for (master_index, master) in self.presentation.slide_master_ids.iter().enumerate() {
            let Some(relationship) = presentation_relationships
                .and_then(|relationships| relationships.get_by_id(&master.relationship_id))
            else {
                missing_theme_relationships.push(ValidationIssue::MissingThemeRel {
                    master: master_index,
                });
                continue;
            };
            let master_part =
                OpcPackage::resolve_rel_target(&self.presentation_part, &relationship.target);
            let has_theme = self
                .package
                .get_part_rels(&master_part)
                .is_some_and(|relationships| {
                    relationships.items.iter().any(|relationship| {
                        relationship.rel_type == rel_types::THEME
                            && !relationship_is_external(relationship)
                    })
                });
            if !has_theme {
                missing_theme_relationships.push(ValidationIssue::MissingThemeRel {
                    master: master_index,
                });
            }
        }

        let mut invalid_xml = Vec::new();
        let owners = (0..self.slides.len())
            .map(ShapeOwner::Slide)
            .chain((0..self.layouts.len()).map(ShapeOwner::Layout))
            .chain((0..self.masters.len()).map(ShapeOwner::Master));
        for owner in owners {
            let Ok(part) = self.owner_part_name(owner) else {
                continue;
            };
            let mut names = PptXmlNames::default();
            let Some(xml) = self.current_part_xml(part) else {
                continue;
            };
            match ppt_xml_frontiers(&xml, &mut names) {
                Ok(scan) => invalid_xml.extend(scan.islands.iter().map(|island| {
                    ValidationIssue::InvalidXmlChild {
                        part: part.to_owned(),
                        path: names.path(island.route),
                        message: island.message.to_owned(),
                    }
                })),
                Err(error) => invalid_xml.push(ValidationIssue::InvalidXmlChild {
                    part: part.to_owned(),
                    path: "/".to_owned(),
                    message: error.to_string(),
                }),
            }
        }
        duplicate_shape_ids
            .into_iter()
            .chain(out_of_range_slide_ids)
            .chain(duplicate_slide_ids)
            .chain(missing_content_types)
            .chain(dangling_relationships)
            .chain(unreachable_targets)
            .chain(empty_text_bodies)
            .chain(duplicate_placeholder_indices)
            .chain(orphan_media)
            .chain(custom_show_references)
            .chain(missing_layout_relationships)
            .chain(missing_theme_relationships)
            .chain(invalid_xml)
            .collect()
    }

    fn current_part_xml(&self, part_name: &str) -> Option<Vec<u8>> {
        if part_name.eq_ignore_ascii_case(&self.presentation_part) {
            return self.presentation.to_xml().ok();
        }
        if let Some(slide) = self
            .slides
            .iter()
            .find(|slide| slide.part_name.eq_ignore_ascii_case(part_name))
        {
            return slide.slide.to_xml().ok();
        }
        if let Some(notes) = self
            .slides
            .iter()
            .filter_map(|slide| slide.notes.as_ref())
            .find(|notes| notes.part_name.eq_ignore_ascii_case(part_name))
        {
            return notes.notes.to_xml().ok();
        }
        if let Some(record) = self
            .masters
            .iter()
            .find(|record| record.dirty && record.part_name.eq_ignore_ascii_case(part_name))
        {
            return record.master.as_ref().ok()?.to_xml().ok();
        }
        if let Some(record) = self
            .layouts
            .iter()
            .find(|record| record.dirty && record.part_name.eq_ignore_ascii_case(part_name))
        {
            return record.layout.to_xml().ok();
        }
        if let Some(record) = self
            .themes
            .iter()
            .find(|record| record.dirty && record.part_name.eq_ignore_ascii_case(part_name))
        {
            return record.theme.to_xml().ok();
        }
        self.package.get_part(part_name).map(<[u8]>::to_vec)
    }

    /// Returns the number of slides in presentation order.
    pub fn len(&self) -> usize {
        self.slides.len()
    }

    /// Returns whether the presentation has no slides.
    pub fn is_empty(&self) -> bool {
        self.slides.is_empty()
    }

    /// Returns one slide by zero-based presentation index.
    pub fn slide(&self, index: usize) -> Option<SlideRef<'_>> {
        self.slides.get(index).map(|record| slide_ref(record))
    }

    /// Returns one slide for in-place mutation by zero-based index.
    pub fn slide_mut(&mut self, index: usize) -> Option<SlideMut<'_>> {
        self.slides.get(index)?;
        Some(slide_mut(self, index))
    }

    /// Returns the shapes of one slide, or of one group on it, for adding
    /// shapes.
    ///
    /// `group` holds one z-order index per nesting level, from the slide's
    /// own shapes down to the group, and is empty for the slide's own shapes.
    /// A missing slide or a path that does not end at a group returns `None`.
    pub fn shapes_mut(&mut self, slide_index: usize, group: &[usize]) -> Option<ShapesMut<'_>> {
        self.shapes_mut_at(ShapeOwner::Slide(slide_index), group)
            .ok()
    }

    /// Returns the actual shape collection of a slide, layout or master.
    /// Missing owners and paths that do not end at a group return a checked error.
    pub fn shapes_mut_at(&mut self, owner: ShapeOwner, group: &[usize]) -> Result<ShapesMut<'_>> {
        let tree = &mut self.owner_data_mut(owner)?.shape_tree;
        if !group.is_empty() {
            group_at_mut(&mut tree.children, group).ok_or_else(|| {
                invalid_shape_mutation("shape collection", "path is not a physical group")
            })?;
        }
        Ok(ShapesMut {
            presentation: self,
            owner,
            group: group.to_vec(),
        })
    }

    /// Iterates slides in `p:sldIdLst` order.
    pub fn slides(&self) -> impl ExactSizeIterator<Item = SlideRef<'_>> {
        self.slides.iter().map(|record| slide_ref(record))
    }

    /// For each slide in order, the index in `earlier` of the slide whose
    /// record it still shares, or `None` for a slide changed or added since.
    ///
    /// A clone shares every slide record with its source until an edit
    /// copies one, so a caller holding both can find the slides an edit
    /// touched without comparing their content.
    #[doc(hidden)]
    pub fn unchanged_slides_since(&self, earlier: &Presentation) -> Vec<Option<usize>> {
        let origins = earlier
            .slides
            .iter()
            .enumerate()
            .map(|(index, record)| (Arc::as_ptr(record), index))
            .collect::<HashMap<_, _>>();
        self.slides
            .iter()
            .map(|record| origins.get(&Arc::as_ptr(record)).copied())
            .collect()
    }

    /// Whether every layout and master record is still the one of `earlier`,
    /// in the same order.
    #[doc(hidden)]
    pub fn unchanged_layouts_and_masters_since(&self, earlier: &Presentation) -> bool {
        fn shared<T>(records: &[Arc<T>], earlier: &[Arc<T>]) -> bool {
            records.len() == earlier.len()
                && records
                    .iter()
                    .zip(earlier)
                    .all(|(record, earlier)| Arc::ptr_eq(record, earlier))
        }
        shared(&self.layouts, &earlier.layouts) && shared(&self.masters, &earlier.masters)
    }

    /// Replaces literal text across regular DrawingML runs in every editable shape.
    ///
    /// Replacement text retains the formatting and opaque run content of the
    /// first matched run. Unmatched prefixes and suffixes stay in their
    /// original runs. Groups and table cells are traversed recursively, while
    /// preserved alternate-content branches remain untouched.
    pub fn replace_text(&mut self, placeholder: &str, value: &str) -> usize {
        if placeholder.is_empty() {
            return 0;
        }
        // Stored as the run text setters store it, so it can be saved.
        let value = &oxml_drawing::text::escape_invalid_xml_characters(value);
        // A slide without a match keeps its record, so a shared one is not
        // copied and callers can tell the changed slides by pointer identity.
        self.slides
            .iter_mut()
            .filter(|record| slide_record_has_text(record, placeholder))
            .map(|record| {
                replace_text_in_slide_record(Arc::make_mut(record), placeholder, value, true)
            })
            .sum()
    }

    /// Replaces literal slide and speaker-note text on a staged candidate.
    ///
    /// The candidate is serialized before it replaces the live presentation,
    /// so a malformed retained subtree cannot publish a partial mutation.
    pub fn try_replace_text(&mut self, placeholder: &str, value: &str) -> Result<usize> {
        require_replacement_placeholder(placeholder)?;
        let mut candidate = self.clone();
        let count = candidate.replace_text(placeholder, value);
        candidate.staged_package(false)?;
        *self = candidate;
        Ok(count)
    }

    /// Applies ordered literal pairs on one candidate and publishes once.
    ///
    /// Counts refer to each pair's current candidate, so pairs may cascade.
    /// A mismatch or serialization failure leaves the original unchanged.
    pub fn try_replace_all_expected(
        &mut self,
        pairs: &[(&str, &str, Option<usize>)],
    ) -> Result<std::result::Result<Vec<usize>, ReplacementCountMismatch>> {
        for (placeholder, _, _) in pairs {
            require_replacement_placeholder(placeholder)?;
        }
        if pairs.is_empty() {
            return Ok(Ok(Vec::new()));
        }
        let mut candidate = self.clone();
        let mut counts = Vec::with_capacity(pairs.len());
        for (index, &(placeholder, value, expected)) in pairs.iter().enumerate() {
            let found = candidate.replace_text(placeholder, value);
            if let Some(expected) = expected.filter(|expected| *expected != found) {
                return Ok(Err(ReplacementCountMismatch {
                    index,
                    placeholder: placeholder.to_owned(),
                    expected,
                    found,
                }));
            }
            counts.push(found);
        }
        candidate.staged_package(false)?;
        *self = candidate;
        Ok(Ok(counts))
    }

    /// Replaces literal text on one slide, and in its speaker notes when
    /// `notes` is true, and returns the count.
    ///
    /// Matching, formatting and traversal are those of
    /// [`Presentation::try_replace_text`], restricted to that slide. Other
    /// slides and their notes are never touched. The replacement runs on a
    /// copy of the slide and its notes, which must serialize before the copy
    /// replaces them. With `expect`, a different count also leaves the slide
    /// unchanged and is returned for the caller to compare.
    pub fn try_replace_slide_text(
        &mut self,
        slide_index: usize,
        placeholder: &str,
        value: &str,
        notes: bool,
        expect: Option<usize>,
    ) -> Result<usize> {
        self.require_slide_index(slide_index)?;
        require_replacement_placeholder(placeholder)?;
        let mut candidate = SlideRecord::clone(&self.slides[slide_index]);
        let value = &oxml_drawing::text::escape_invalid_xml_characters(value);
        let count = replace_text_in_slide_record(&mut candidate, placeholder, value, notes);
        if expect.is_some_and(|expected| expected != count) {
            return Ok(count);
        }
        candidate
            .slide
            .to_xml()
            .map_err(|error| Error::MalformedPart {
                part_name: candidate.part_name.clone(),
                message: error.to_string(),
            })?;
        if let Some(record) = candidate.notes.as_ref().filter(|_| notes) {
            record
                .notes
                .to_xml()
                .map_err(|error| Error::MalformedPart {
                    part_name: record.part_name.clone(),
                    message: error.to_string(),
                })?;
        }
        self.slides[slide_index] = Arc::new(candidate);
        Ok(count)
    }

    /// Returns the optional slide dimensions in EMUs.
    pub fn slide_size(&self) -> Option<(Emu, Emu)> {
        self.presentation
            .slide_size
            .as_ref()
            .map(|size| (size.cx, size.cy))
    }

    /// Replaces only the slide dimensions after validating both values.
    pub fn set_slide_size(&mut self, width: Emu, height: Emu) -> Result<()> {
        self.presentation
            .set_slide_size(width, height)
            .map_err(|error| Error::InvalidPresentationMutation {
                operation: "set slide size",
                message: error.to_string(),
            })
    }

    /// Reads the optional displayed start without flattening absent and zero.
    pub fn slide_number_start(&self) -> Result<Option<u32>> {
        self.presentation
            .first_slide_number()
            .map_err(|error| Error::MalformedPart {
                part_name: self.presentation_part.clone(),
                message: error.to_string(),
            })
    }

    /// Stages checked displayed numbering without changing physical slide IDs.
    pub fn set_slide_number_start(&mut self, value: Option<u32>) -> Result<()> {
        let start = value.unwrap_or(1);
        if let Some(last) = self.slides.len().checked_sub(1) {
            let last = u32::try_from(last)
                .map_err(|_| invalid_slide_mutation("set slide number start", "too many slides"))?;
            start.checked_add(last).ok_or_else(|| {
                invalid_slide_mutation("set slide number start", "displayed slide number overflow")
            })?;
        }
        if self.slide_number_start()? == value {
            return Ok(());
        }
        let mut staged = self.clone();
        staged.presentation.set_first_slide_number(value);
        self.commit_candidate(staged)
    }

    /// Returns shared package core properties without dirtying their source part.
    pub fn core_properties(&self) -> Option<&CoreProperties> {
        self.core_properties.as_ref()
    }

    /// Returns mutable shared core properties, materializing the package model.
    pub fn core_properties_mut(&mut self) -> &mut CoreProperties {
        self.core_properties_dirty = true;
        self.core_properties
            .get_or_insert_with(CoreProperties::default)
    }

    /// Changes known core fields while retaining every unowned imported byte.
    pub fn set_core_properties(&mut self, properties: CoreProperties) -> Result<()> {
        for value in [
            &properties.title,
            &properties.creator,
            &properties.subject,
            &properties.description,
            &properties.keywords,
            &properties.last_modified_by,
            &properties.created,
            &properties.modified,
            &properties.category,
            &properties.content_status,
            &properties.identifier,
            &properties.language,
            &properties.last_printed,
            &properties.revision,
            &properties.version,
        ]
        .into_iter()
        .flatten()
        {
            oxml_core::xml::reject_non_xml_characters("core property", value)
                .map_err(|error| invalid_shape_mutation("core properties", error.to_string()))?;
        }
        properties
            .to_xml()
            .map_err(|error| invalid_shape_mutation("core properties", error.to_string()))?;
        if self.core_properties.as_ref() == Some(&properties) {
            return Ok(());
        }
        let mut candidate = self.clone();
        let xml = if let (Some(old), Some(source)) = (
            self.core_properties.as_ref(),
            self.package.get_part(&self.core_properties_part_name),
        ) {
            patch_core_properties(source, old, &properties)?
        } else {
            if self.package.contains_part(&self.core_properties_part_name) {
                return Err(Error::CorePropertiesPartCollision {
                    part_name: self.core_properties_part_name.clone(),
                });
            }
            properties
                .to_xml()
                .map_err(|error| invalid_shape_mutation("core properties", error.to_string()))?
        };
        candidate
            .package
            .set_part(&self.core_properties_part_name, xml);
        candidate.package.content_types.add_override(
            &self.core_properties_part_name,
            content_types::CORE_PROPERTIES,
        );
        if candidate
            .package
            .package_rels
            .get_by_type(rel_types::CORE_PROPERTIES)
            .is_none()
        {
            candidate.package.package_rels.add(
                rel_types::CORE_PROPERTIES,
                self.core_properties_part_name.trim_start_matches('/'),
            );
        }
        candidate.core_properties = Some(properties);
        candidate.core_properties_dirty = false;
        self.commit_candidate(candidate)
    }

    /// Removes the owned core bundle without changing any other source part.
    pub fn remove_core_properties(&mut self) -> Result<Option<CoreProperties>> {
        let Some(old) = self.core_properties.clone() else {
            return Ok(None);
        };
        let mut candidate = self.clone();
        candidate
            .package
            .remove_part(&self.core_properties_part_name);
        candidate
            .package
            .content_types
            .remove_override(&self.core_properties_part_name);
        candidate
            .package
            .package_rels
            .items
            .retain(|rel| rel.rel_type != rel_types::CORE_PROPERTIES);
        candidate.core_properties = None;
        candidate.core_properties_dirty = false;
        self.commit_candidate(candidate)?;
        Ok(Some(old))
    }

    /// Returns cached application properties without dirtying retained XML.
    pub fn application_properties(&self) -> Option<&AppProperties> {
        self.application_properties.as_ref()
    }

    /// Publishes application properties after staged validation and source preservation.
    pub fn set_application_properties(&mut self, properties: AppProperties) -> Result<()> {
        if let Some(version) = &properties.application_version {
            let bytes = version.as_bytes();
            if bytes.len() != 7
                || bytes[2] != b'.'
                || !bytes[..2].iter().chain(&bytes[3..]).all(u8::is_ascii_digit)
            {
                return Err(invalid_shape_mutation(
                    "application properties",
                    "application_version must be XX.YYYY",
                ));
            }
        }
        let generated = properties
            .to_xml()
            .map_err(|e| invalid_shape_mutation("application properties", e.to_string()))?;
        if self.application_properties.as_ref() == Some(&properties) {
            return Ok(());
        }
        let mut candidate = self.clone();
        let xml = if let Some(name) = property_part(
            &self.package,
            rel_types::EXTENDED_PROPERTIES,
            content_types::EXTENDED_PROPERTIES,
        )? {
            patch_application_properties(
                required_part(&self.package, &name)?,
                self.application_properties.as_ref().ok_or_else(|| {
                    invalid_shape_mutation(
                        "application properties",
                        "missing parsed property owner",
                    )
                })?,
                &properties,
            )?
        } else {
            generated
        };
        publish_property_part(
            &mut candidate.package,
            rel_types::EXTENDED_PROPERTIES,
            content_types::EXTENDED_PROPERTIES,
            "/docProps/app.xml",
            xml,
        )?;
        candidate.application_properties = Some(properties);
        self.commit_candidate(candidate)
    }

    /// Removes the owned application part and relationship together.
    pub fn remove_application_properties(&mut self) -> Result<Option<AppProperties>> {
        let Some(old) = self.application_properties.clone() else {
            return Ok(None);
        };
        let mut candidate = self.clone();
        if let Some(name) = property_part(
            &candidate.package,
            rel_types::EXTENDED_PROPERTIES,
            content_types::EXTENDED_PROPERTIES,
        )? {
            candidate.package.remove_part(&name);
            candidate.package.content_types.remove_override(&name);
            candidate
                .package
                .package_rels
                .items
                .retain(|rel| rel.rel_type != rel_types::EXTENDED_PROPERTIES);
        }
        candidate.application_properties = None;
        self.commit_candidate(candidate)?;
        Ok(Some(old))
    }

    /// Returns custom properties in retained package order.
    pub fn custom_properties(&self) -> &[CustomProperty] {
        self.custom_properties
            .as_ref()
            .map(|p| p.properties.as_slice())
            .unwrap_or_default()
    }
    /// Finds a case-sensitive custom property name.
    pub fn custom_property(&self, name: &str) -> Option<&CustomProperty> {
        self.custom_properties()
            .iter()
            .find(|p| p.name.as_deref() == Some(name))
    }
    /// Changes one named value while retaining its existing identity and source order.
    pub fn set_custom_property(&mut self, mut property: CustomProperty) -> Result<()> {
        let name = property
            .name
            .clone()
            .filter(|n| !n.is_empty())
            .ok_or_else(|| {
                invalid_shape_mutation("custom properties", "property name must not be empty")
            })?;
        oxml_core::xml::reject_non_xml_characters("custom property name", &name)
            .map_err(|e| invalid_shape_mutation("custom properties", e.to_string()))?;
        if let Some(old) = self.custom_property(&name) {
            if old.value == property.value {
                return Ok(());
            }
            if matches!(old.value, CustomPropertyValue::Raw(_)) {
                return Err(invalid_shape_mutation(
                    "custom properties",
                    "unsupported retained custom values are read-only",
                ));
            }
            property.pid = old.pid;
            property.fmtid = old.fmtid.clone();
        } else if property.pid < 2
            || self
                .custom_properties()
                .iter()
                .any(|p| p.pid == property.pid)
        {
            return Err(invalid_shape_mutation(
                "custom properties",
                "custom property PID must be unique and at least 2",
            ));
        }
        oxml_core::xml::reject_non_xml_characters("custom property fmtid", &property.fmtid)
            .map_err(|e| invalid_shape_mutation("custom properties", e.to_string()))?;
        let value = custom_value_xml(&property.value)?;
        let mut candidate = self.clone();
        let properties = candidate
            .custom_properties
            .get_or_insert_with(CustomProperties::default);
        if let Some(index) = properties
            .properties
            .iter()
            .position(|p| p.name.as_deref() == Some(&name))
        {
            properties.properties[index] = property.clone();
        } else {
            properties.properties.push(property.clone());
        }
        let part = property_part(
            &self.package,
            rel_types::CUSTOM_PROPERTIES,
            content_types::CUSTOM_PROPERTIES,
        )?;
        let xml = if let Some(part) = part {
            patch_custom_property(
                required_part(&self.package, &part)?,
                &name,
                Some((&property, &value)),
            )?
        } else {
            properties
                .to_xml()
                .map_err(|e| invalid_shape_mutation("custom properties", e.to_string()))?
        };
        publish_property_part(
            &mut candidate.package,
            rel_types::CUSTOM_PROPERTIES,
            content_types::CUSTOM_PROPERTIES,
            "/docProps/custom.xml",
            xml,
        )?;
        self.commit_candidate(candidate)
    }
    /// Removes one property without changing other values or order.
    pub fn remove_custom_property(&mut self, name: &str) -> Result<Option<CustomProperty>> {
        let Some(old) = self.custom_property(name).cloned() else {
            return Ok(None);
        };
        let mut candidate = self.clone();
        let part = property_part(
            &self.package,
            rel_types::CUSTOM_PROPERTIES,
            content_types::CUSTOM_PROPERTIES,
        )?
        .ok_or_else(|| invalid_shape_mutation("custom properties", "property bundle is absent"))?;
        let xml = patch_custom_property(required_part(&self.package, &part)?, name, None)?;
        candidate.package.set_part(&part, xml);
        candidate
            .custom_properties
            .as_mut()
            .expect("existing property")
            .properties
            .retain(|p| p.name.as_deref() != Some(name));
        self.commit_candidate(candidate)?;
        Ok(Some(old))
    }

    /// Returns the current master model, retaining an unprojectable source as an error.
    pub fn master(&self, index: usize) -> Option<&CT_SlideMaster> {
        self.masters.get(index)?.master.as_ref().ok()
    }

    pub fn master_count(&self) -> usize {
        self.masters.len()
    }

    /// Returns the actual optional producer master ID.
    pub fn master_id(&self, index: usize) -> Option<u32> {
        self.masters.get(index)?.id
    }

    pub fn layout(&self, index: usize) -> Option<&CT_SlideLayout> {
        self.layouts.get(index).map(|record| &record.layout)
    }

    fn owner_part_name(&self, owner: ShapeOwner) -> Result<&str> {
        if let ShapeOwner::Slide(index) = owner {
            self.require_slide_index(index)?;
        }
        let part = match owner {
            ShapeOwner::Slide(index) => self
                .slides
                .get(index)
                .map(|record| record.part_name.as_str()),
            ShapeOwner::Layout(index) => self
                .layouts
                .get(index)
                .map(|record| record.part_name.as_str()),
            ShapeOwner::Master(index) => self
                .masters
                .get(index)
                .map(|record| record.part_name.as_str()),
        };
        part.ok_or_else(|| invalid_shape_mutation("part owner", format!("missing {owner:?}")))
    }

    fn owner_data(&self, owner: ShapeOwner) -> Result<&CT_CommonSlideData> {
        self.owner_part_name(owner)?;
        match owner {
            ShapeOwner::Slide(index) => Ok(&self.slides[index].slide.common_slide_data),
            ShapeOwner::Layout(index) => Ok(&self.layouts[index].layout.common_slide_data),
            ShapeOwner::Master(index) => self.masters[index]
                .master
                .as_ref()
                .map(|master| &master.common_slide_data)
                .map_err(|message| Error::MalformedPart {
                    part_name: self.masters[index].part_name.clone(),
                    message: message.clone(),
                }),
        }
    }

    fn owner_data_mut(&mut self, owner: ShapeOwner) -> Result<&mut CT_CommonSlideData> {
        self.owner_data(owner)?;
        match owner {
            ShapeOwner::Slide(index) => Ok(&mut Arc::make_mut(&mut self.slides[index])
                .slide
                .common_slide_data),
            ShapeOwner::Layout(index) => {
                let record = Arc::make_mut(&mut self.layouts[index]);
                record.dirty = true;
                Ok(&mut record.layout.common_slide_data)
            }
            ShapeOwner::Master(index) => {
                let record = Arc::make_mut(&mut self.masters[index]);
                record.dirty = true;
                record
                    .master
                    .as_mut()
                    .map(|master| &mut master.common_slide_data)
                    .map_err(|message| Error::MalformedPart {
                        part_name: record.part_name.clone(),
                        message: message.clone(),
                    })
            }
        }
    }

    /// Reads a direct master title/body/other paragraph level, numbered one through nine.
    pub fn master_text_style(
        &self,
        master_index: usize,
        style: &str,
        level: usize,
    ) -> Result<Option<&CT_TextParagraphProperties>> {
        if !(1..=9).contains(&level) {
            return Err(invalid_shape_mutation(
                "master text style",
                "level must be from 1 through 9",
            ));
        }
        let master = self.master(master_index).ok_or_else(|| {
            invalid_shape_mutation("master text style", "master owner is absent or malformed")
        })?;
        let styles = master.text_styles.as_ref();
        let list = match style {
            "title" => styles.map(|styles| &styles.title_style),
            "body" => styles.map(|styles| &styles.body_style),
            "other" => styles.map(|styles| &styles.other_style),
            _ => {
                return Err(invalid_shape_mutation(
                    "master text style",
                    "style must be title, body or other",
                ));
            }
        };
        Ok(list.and_then(|list| list.level(level)))
    }

    /// Changes only the selected qualified level source and validates before publication.
    pub fn set_master_text_style(
        &mut self,
        master_index: usize,
        style: &str,
        level: usize,
        properties: CT_TextParagraphProperties,
    ) -> Result<()> {
        let current = self
            .master_text_style(master_index, style, level)?
            .cloned()
            .unwrap_or_default();
        if current == properties {
            return Ok(());
        }
        let mut candidate = self.clone();
        candidate.package = self.staged_package(true)?;
        let part = self
            .master_part(master_index)?
            .ok_or_else(|| invalid_shape_mutation("master text style", "master owner is absent"))?;
        let source = required_part(&candidate.package, &part)?;
        let (children, root_end) =
            property_child_ranges(source, rpptx_oxml::namespace::P_NS, "sldMaster")?;
        let styles = children
            .iter()
            .filter(|(uri, name, _, _)| {
                uri.as_deref() == Some(rpptx_oxml::namespace::P_NS) && name == "txStyles"
            })
            .collect::<Vec<_>>();
        if styles.len() > 1 {
            return Err(footer_malformed(&part, "master has ambiguous text styles"));
        }
        let tag = format!("a:lvl{level}pPr");
        let mut writer = quick_xml::Writer::new(Vec::new());
        properties
            .write_xml(&mut writer, &tag)
            .map_err(|error| footer_malformed(&part, error.to_string()))?;
        let mut replacement = writer.into_inner();
        let first_end = replacement
            .iter()
            .position(|byte| *byte == b'>')
            .ok_or_else(|| footer_malformed(&part, "level source has no start token"))?;
        let insertion = if replacement[first_end - 1] == b'/' {
            first_end - 1
        } else {
            first_end
        };
        let mut fragment_reader = quick_xml::Reader::from_reader(replacement.as_slice());
        let start = match fragment_reader.read_event().map_err(OpcError::from)? {
            XmlEvent::Start(start) | XmlEvent::Empty(start) => start,
            _ => return Err(footer_malformed(&part, "level source is not an element")),
        };
        let mut has_a = false;
        for attribute in start.attributes() {
            let attribute = attribute
                .map_err(quick_xml::Error::from)
                .map_err(OpcError::from)?;
            if attribute.key.as_ref() == b"xmlns:a" {
                if attribute
                    .decoded_and_normalized_value(XmlVersion::Implicit1_0, start.decoder())
                    .map_err(OpcError::from)?
                    .as_ref()
                    != A_NS
                {
                    return Err(footer_malformed(&part, "level canonical prefix is rebound"));
                }
                has_a = true;
            }
        }
        if !has_a {
            replacement.splice(insertion..insertion, format!(" xmlns:a=\"{A_NS}\"").bytes());
        }
        let style_tag = format!("{style}Style");
        let (begin, end, changed) = if let Some((_, _, begin, end)) = styles.first() {
            let mut styles_source = portable_owned_fragment(source, *begin, *end)?;
            let (style_children, _) =
                property_child_ranges(&styles_source, rpptx_oxml::namespace::P_NS, "txStyles")?;
            let selected = style_children
                .iter()
                .filter(|(uri, name, _, _)| {
                    uri.as_deref() == Some(rpptx_oxml::namespace::P_NS) && name == &style_tag
                })
                .collect::<Vec<_>>();
            if selected.len() != 1 {
                return Err(footer_malformed(
                    &part,
                    "selected master style is absent or ambiguous",
                ));
            }
            let (_, _, style_begin, style_end) = selected[0];
            let mut list_source =
                portable_owned_fragment(&styles_source, *style_begin, *style_end)?;
            let (levels, list_end) =
                property_child_ranges(&list_source, rpptx_oxml::namespace::P_NS, &style_tag)?;
            let level_tag = format!("lvl{level}pPr");
            let selected_levels = levels
                .iter()
                .filter(|(uri, name, _, _)| uri.as_deref() == Some(A_NS) && name == &level_tag)
                .collect::<Vec<_>>();
            if selected_levels.len() > 1 {
                return Err(footer_malformed(
                    &part,
                    "selected master level is ambiguous",
                ));
            }
            let range = if let Some((_, _, begin, end)) = selected_levels.first() {
                *begin..*end
            } else {
                let before = levels
                    .iter()
                    .find(|(uri, name, _, _)| {
                        uri.as_deref() == Some(A_NS)
                            && name
                                .strip_prefix("lvl")
                                .and_then(|name| name.strip_suffix("pPr"))
                                .and_then(|number| number.parse::<usize>().ok())
                                .is_some_and(|number| number > level)
                    })
                    .map(|(_, _, begin, _)| *begin)
                    .unwrap_or(list_end);
                before..before
            };
            list_source.splice(range, replacement);
            styles_source.splice(*style_begin..*style_end, list_source);
            (*begin, *end, styles_source)
        } else {
            let mut fragment = format!(
                "<p:txStyles xmlns:p=\"{}\" xmlns:a=\"{A_NS}\">",
                rpptx_oxml::namespace::P_NS
            )
            .into_bytes();
            for slot in ["title", "body", "other"] {
                fragment.extend_from_slice(format!("<p:{slot}Style>").as_bytes());
                if slot == style {
                    fragment.extend_from_slice(&replacement);
                }
                fragment.extend_from_slice(format!("</p:{slot}Style>").as_bytes());
            }
            fragment.extend_from_slice(b"</p:txStyles>");
            let before = children
                .iter()
                .find(|(uri, name, _, _)| {
                    uri.as_deref() == Some(rpptx_oxml::namespace::P_NS) && name == "extLst"
                })
                .map(|(_, _, begin, _)| *begin)
                .unwrap_or(root_end);
            (before, before, fragment)
        };
        let mut changed_source = source.to_vec();
        changed_source.splice(begin..end, changed);
        let master = CT_SlideMaster::from_xml(&changed_source)
            .map_err(|error| footer_malformed(&part, error.to_string()))?;
        candidate.package.set_part(&part, changed_source);
        Arc::make_mut(&mut candidate.masters[master_index]).master = Ok(master);
        Arc::make_mut(&mut candidate.masters[master_index]).dirty = false;
        candidate.commit_owned_parts(None)?;
        *self = candidate;
        Ok(())
    }

    /// Reads only the directly owned background fill without materializing inheritance.
    pub fn background_fill_at(&self, owner: ShapeOwner) -> Result<Option<&Fill>> {
        Ok(self
            .owner_data(owner)?
            .background
            .as_ref()
            .and_then(|background| match background.rendering() {
                rpptx_oxml::slide_parts::BackgroundRendering::Properties(fill) => fill.as_deref(),
                _ => None,
            }))
    }

    /// Reads whether the part carries its own background choice.
    pub fn has_explicit_background_at(&self, owner: ShapeOwner) -> Result<bool> {
        Ok(self.owner_data(owner)?.background.is_some())
    }

    /// Detaches the effective background into its actual owner, or restores inheritance.
    pub fn set_follow_master_background_at(
        &mut self,
        owner: ShapeOwner,
        follow: bool,
    ) -> Result<()> {
        self.owner_data(owner)?;
        if matches!(owner, ShapeOwner::Master(_)) {
            return Err(invalid_shape_mutation(
                "follow master background",
                "masters have no parent background",
            ));
        }
        let explicit = self.owner_data(owner)?.background.is_some();
        if follow == !explicit {
            return Ok(());
        }
        let mut candidate = self.clone();
        candidate.package = self.staged_package(true)?;
        if follow {
            candidate.owner_data_mut(owner)?.background = None;
        } else {
            let mut ancestors = Vec::new();
            let layout = match owner {
                ShapeOwner::Slide(index) => self.slide_layout_index(index),
                ShapeOwner::Layout(index) => Some(index),
                ShapeOwner::Master(_) => unreachable!(),
            };
            if let Some(index) = layout {
                if matches!(owner, ShapeOwner::Slide(_)) {
                    ancestors.push(ShapeOwner::Layout(index));
                }
                ancestors.push(ShapeOwner::Master(self.layout_master_index(index)?));
            }
            let inherited = ancestors.into_iter().find_map(|source_owner| {
                self.owner_data(source_owner)
                    .ok()?
                    .background
                    .as_ref()
                    .map(|background| (source_owner, background.clone()))
            });
            let background = if let Some((source_owner, background)) = inherited {
                let source_part = self.owner_part_name(source_owner)?;
                let source = required_part(&candidate.package, source_part)?;
                let raw = background.raw_xml();
                let positions = source
                    .windows(raw.len())
                    .enumerate()
                    .filter_map(|(index, bytes)| (bytes == raw).then_some(index))
                    .collect::<Vec<_>>();
                if positions.len() != 1 {
                    return Err(invalid_shape_mutation(
                        "follow master background",
                        "background source is absent or ambiguous",
                    ));
                }
                let mut portable =
                    portable_owned_fragment(source, positions[0], positions[0] + raw.len())?;
                let destination_part = self.owner_part_name(owner)?.to_owned();
                let mut relationships = candidate
                    .package
                    .get_part_rels(&destination_part)
                    .cloned()
                    .unwrap_or_default();
                let mut remapped = HashMap::new();
                for id in relationship_ids(&portable).map_err(|error| {
                    invalid_shape_mutation("follow master background", error.to_string())
                })? {
                    let relationship = candidate
                        .package
                        .get_part_rels(source_part)
                        .and_then(|relationships| relationships.get_by_id(&id))
                        .ok_or_else(|| {
                            footer_malformed(
                                source_part,
                                format!("background relationship {id} is absent"),
                            )
                        })?;
                    if relationship.rel_type != rel_types::IMAGE
                        || relationship_is_external(relationship)
                    {
                        return Err(footer_malformed(
                            source_part,
                            format!("unsupported background relationship {id}"),
                        ));
                    }
                    let target = OpcPackage::resolve_rel_target(source_part, &relationship.target);
                    required_part(&candidate.package, &target)?;
                    let existing = relationships
                        .items
                        .iter()
                        .find(|item| {
                            item.rel_type == rel_types::IMAGE
                                && !relationship_is_external(item)
                                && OpcPackage::resolve_rel_target(&destination_part, &item.target)
                                    == target
                        })
                        .map(|item| item.id.clone());
                    let fresh = existing.unwrap_or_else(|| {
                        relationships.add(
                            rel_types::IMAGE,
                            &relative_part_target(&destination_part, &target),
                        )
                    });
                    remapped.insert(id, fresh);
                }
                portable = rewrite_exact_rel_ids(&portable, &remapped).map_err(|error| {
                    invalid_shape_mutation("follow master background", error.to_string())
                })?;
                candidate
                    .package
                    .set_part_rels(&destination_part, relationships);
                rpptx_oxml::slide_parts::CT_Background::from_xml(&portable).map_err(|error| {
                    invalid_shape_mutation("follow master background", error.to_string())
                })?
            } else {
                rpptx_oxml::slide_parts::CT_Background::from_fill(Fill::NoFill(NoFill::default()))
                    .map_err(|error| {
                    invalid_shape_mutation("follow master background", error.to_string())
                })?
            };
            candidate.owner_data_mut(owner)?.background = Some(background);
        }
        let previous = self.owner_relationship_ids(owner)?;
        candidate.release_unused_owner_images(owner, &previous)?;
        candidate.commit_owned_parts(None)?;
        *self = candidate;
        Ok(())
    }

    /// Changes an optional slide or layout visibility policy without changing master shapes.
    pub fn set_show_master_shapes_at(
        &mut self,
        owner: ShapeOwner,
        show: Option<bool>,
    ) -> Result<()> {
        self.owner_data(owner)?;
        let current = match owner {
            ShapeOwner::Slide(index) => self.slides[index].slide.show_master_shapes,
            ShapeOwner::Layout(index) => self.layouts[index].layout.show_master_shapes,
            ShapeOwner::Master(_) => {
                return Err(invalid_shape_mutation(
                    "show master shapes",
                    "masters have no showMasterSp policy",
                ));
            }
        };
        if current == show {
            return Ok(());
        }
        let mut candidate = self.clone();
        match owner {
            ShapeOwner::Slide(index) => {
                Arc::make_mut(&mut candidate.slides[index])
                    .slide
                    .show_master_shapes = show
            }
            ShapeOwner::Layout(index) => {
                Arc::make_mut(&mut candidate.layouts[index])
                    .layout
                    .show_master_shapes = show;
                Arc::make_mut(&mut candidate.layouts[index]).dirty = true;
            }
            ShapeOwner::Master(_) => unreachable!(),
        }
        candidate.commit_owned_parts(None)?;
        *self = candidate;
        Ok(())
    }

    /// Reads optional local visibility, preserving absence versus an explicit flag.
    pub fn show_master_shapes_at(&self, owner: ShapeOwner) -> Result<Option<bool>> {
        self.owner_data(owner)?;
        match owner {
            ShapeOwner::Slide(index) => Ok(self.slides[index].slide.show_master_shapes),
            ShapeOwner::Layout(index) => Ok(self.layouts[index].layout.show_master_shapes),
            ShapeOwner::Master(_) => Err(invalid_shape_mutation(
                "show master shapes",
                "masters have no showMasterSp policy",
            )),
        }
    }

    /// Reads one physical child path in a slide, layout or master.
    pub fn part_shape_at(&self, owner: ShapeOwner, path: &[usize]) -> Result<ShapeRef<'_>> {
        let missing = || invalid_shape_mutation("shape owner", "missing physical path");
        let (first, rest) = path.split_first().ok_or_else(missing)?;
        let mut shape = self
            .owner_data(owner)?
            .shape_tree
            .children
            .get(*first)
            .map(shape_ref)
            .ok_or_else(missing)?;
        for index in rest {
            shape = shape.child(*index).ok_or_else(missing)?;
        }
        Ok(shape)
    }

    /// Edits the actual part-owned child, including group descendants.
    pub fn shape_mut_at(&mut self, owner: ShapeOwner, path: &[usize]) -> Result<ShapeMut<'_>> {
        child_at(&self.owner_data(owner)?.shape_tree.children, path)
            .ok_or_else(|| invalid_shape_mutation("shape owner", "missing physical path"))?;
        Ok(owned_shape_mut(self, owner, path.to_vec()))
    }

    fn part_inherited_target_transform(
        &self,
        owner: ShapeOwner,
        target: &ShapeTreeChild,
        operation: &'static str,
    ) -> Result<CT_Transform2D> {
        #[cfg(feature = "render")]
        if let ShapeOwner::Layout(index) = owner
            && let Some(placeholder) = shape_placeholder(target)
        {
            let (layout, master) = self.layout_and_master(index)?;
            if let Some(transform) = inherited_xfrm(placeholder, layout, &master)
                .filter(|transform| transform.offset.is_some() && transform.extent.is_some())
            {
                return Ok(transform.clone());
            }
        }
        let _ = (owner, target);
        Err(invalid_shape_mutation(
            operation,
            "the part shape has no position and size",
        ))
    }

    /// Materializes a placeholder through the actual part inheritance chain.
    #[cfg(feature = "render")]
    pub fn materialize_owner_geometry(&mut self, owner: ShapeOwner, path: &[usize]) -> Result<()> {
        if let ShapeOwner::Slide(index) = owner {
            return self.materialize_geometry(index, path);
        }
        let target = self.part_shape_at(owner, path)?.child;
        let own = shape_transform(target);
        if own.is_some_and(|transform| transform.offset.is_some() && transform.extent.is_some()) {
            return Ok(());
        }
        if shape_placeholder(target).is_none() {
            return Ok(());
        }
        let inherited =
            self.part_inherited_target_transform(owner, target, "materialize geometry")?;
        let mut transform = own.cloned().unwrap_or_else(|| inherited.clone());
        transform.offset = transform.offset.or(inherited.offset);
        transform.extent = transform.extent.or(inherited.extent);
        let child = child_at_mut(&mut self.owner_data_mut(owner)?.shape_tree.children, path)
            .expect("the physical path was checked");
        *shape_mut(child).transform_mut("materialize geometry")? = transform;
        Ok(())
    }

