    #[test]
    fn validation_xml_scan_is_prefix_tolerant_and_non_mutating() {
        let presentation = presentation_with_slide();
        let relationship_id = presentation.presentation.slide_ids[0]
            .relationship_id
            .clone();
        let presentation = presentation_with_custom_show(&relationship_id);
        let before = presentation
            .package
            .get_part(&presentation.presentation_part)
            .unwrap()
            .to_vec();

        assert!(presentation.validate().is_empty());
        assert_eq!(
            presentation
                .package
                .get_part(&presentation.presentation_part)
                .unwrap(),
            before
        );
    }

    #[test]
    fn fx208_footer_owned_fields_are_unique_idempotent_and_atomic() {
        let mut p = Presentation::new().unwrap();
        p.add_slide(0).unwrap();
        p.add_slide(1).unwrap();
        let settings = HeaderFooter {
            slide_number: true,
            footer: Some("F208 footer".into()),
            date: HeaderFooterDate::Automatic {
                field_type: "datetime13".into(),
                text: None,
            },
        };
        p.set_header_footer(&settings, true).unwrap();
        assert_eq!(p.slide_header_footer(0), Some(HeaderFooter::default()));
        assert_eq!(p.slide_header_footer(1), Some(settings.clone()));
        let saved = p.to_bytes().unwrap();
        p.set_header_footer(&settings, true).unwrap();
        assert_eq!(
            p.to_bytes().unwrap(),
            saved,
            "identical footer publication must retain source"
        );
        let mut reopened = Presentation::from_bytes(&saved).unwrap();
        assert_eq!(reopened.slide_header_footer(1), Some(settings.clone()));
        reopened.add_slide(1).unwrap();
        assert_eq!(reopened.slide_header_footer(2), Some(settings.clone()));
        let identities = reopened.field_identity_inventory().unwrap();
        let package = reopened.staged_package(true).unwrap();
        let mut actual = Vec::new();
        for (name, xml) in &package.parts {
            if !name.contains("/slides/") || !name.ends_with(".xml") {
                continue;
            }
            let slide = CT_Slide::from_xml(xml).unwrap();
            fn fields(children: &[ShapeTreeChild], actual: &mut Vec<String>) {
                for child in children {
                    match child {
                        ShapeTreeChild::Shape(shape) => {
                            if let Some(body) = &shape.text_body {
                                for run in body
                                    .paragraphs()
                                    .iter()
                                    .flat_map(|paragraph| &paragraph.runs)
                                {
                                    if let TextRun::Field(field) = run {
                                        actual.push(field.id.clone());
                                    }
                                }
                            }
                        }
                        ShapeTreeChild::GroupShape(group) => fields(&group.children, actual),
                        _ => {}
                    }
                }
            }
            fields(&slide.common_slide_data.shape_tree.children, &mut actual);
        }
        assert_eq!(actual.len(), 4);
        assert_eq!(actual.iter().collect::<HashSet<_>>().len(), actual.len());
        assert!(actual.iter().all(|id| identities.contains(id)));
        let cached = HeaderFooter {
            date: HeaderFooterDate::Automatic {
                field_type: "datetime1".into(),
                text: Some("same displayed text".into()),
            },
            ..settings.clone()
        };
        reopened.set_slide_header_footer(1, &cached).unwrap();
        assert_eq!(reopened.slide_header_footer(1).unwrap().date, cached.date);
        let fixed = HeaderFooter {
            date: HeaderFooterDate::Fixed("same displayed text".into()),
            ..cached
        };
        reopened.set_slide_header_footer(1, &fixed).unwrap();
        assert_eq!(reopened.slide_header_footer(1).unwrap().date, fixed.date);
        let fixed_bytes = reopened.to_bytes().unwrap();
        assert_eq!(
            Presentation::from_bytes(&fixed_bytes)
                .unwrap()
                .slide_header_footer(1)
                .unwrap()
                .date,
            fixed.date
        );
        reopened.set_slide_header_footer(1, &fixed).unwrap();
        assert_eq!(reopened.to_bytes().unwrap(), fixed_bytes);
        let before = reopened.to_bytes().unwrap();
        let bad = HeaderFooter {
            footer: Some("invalid\0text".into()),
            ..settings
        };
        assert!(reopened.set_header_footer(&bad, false).is_err());
        assert_eq!(reopened.to_bytes().unwrap(), before);
    }

    #[test]
    fn fx208_header_footer_policy_retains_presence_and_scope_without_paint_projection() {
        let mut deck = Presentation::new().unwrap();
        deck.add_slide(6).unwrap();
        let layout = deck.slide_layout_index(0).unwrap();
        let (master_part, mut master) = deck.layout_master_part(layout).unwrap();
        master.header_footer = None;
        deck.package
            .set_part(&master_part, master.to_xml().unwrap());
        deck = Presentation::from_package(deck.staged_package(true).unwrap()).unwrap();
        Arc::make_mut(&mut deck.layouts[layout])
            .layout
            .header_footer = None;
        assert_eq!(deck.slide_header_footer_policy(0).unwrap(), None);
        assert!(!deck.slide_header_footer(0).unwrap().slide_number);
        master.header_footer = Some(CT_HeaderFooter::new(Some(false), None, Some(true), None));
        deck.package
            .set_part(&master_part, master.to_xml().unwrap());
        deck = Presentation::from_package(deck.staged_package(true).unwrap()).unwrap();
        assert_eq!(
            deck.slide_header_footer_policy(0).unwrap(),
            Some((
                "master",
                HeaderFooterFlags {
                    date: None,
                    footer: Some(true),
                    slide_number: Some(false)
                }
            ))
        );
        Arc::make_mut(&mut deck.layouts[layout])
            .layout
            .header_footer = Some(CT_HeaderFooter::new(None, None, Some(false), Some(true)));
        assert_eq!(
            deck.slide_header_footer_policy(0).unwrap(),
            Some((
                "layout",
                HeaderFooterFlags {
                    date: Some(true),
                    footer: Some(false),
                    slide_number: None
                }
            ))
        );
        let owned = deck.slide_header_footer(0).unwrap();
        assert!(
            !owned.slide_number && owned.footer.is_none() && owned.date == HeaderFooterDate::Off
        );
        let layout_part = deck.layouts[layout].part_name.clone();
        deck.package
            .set_part(&layout_part, deck.layouts[layout].layout.to_xml().unwrap());
        let reopened = Presentation::from_bytes(&deck.to_bytes().unwrap()).unwrap();
        assert_eq!(
            reopened.slide_header_footer_policy(0).unwrap(),
            deck.slide_header_footer_policy(0).unwrap()
        );
        assert_eq!(reopened.slide_header_footer(0), deck.slide_header_footer(0));
    }

    #[test]
    fn fx208_fields_retain_cache_presence_and_global_identity_atomically() {
        let mut deck = Presentation::new().unwrap();
        deck.add_slide(6).unwrap();
        deck.slide_mut(0)
            .unwrap()
            .add_textbox(Emu(0), Emu(0), Emu(914400), Emu(914400))
            .unwrap();
        let mut ids = std::collections::HashSet::new();
        for kind in FIELD_TYPES {
            for cache in [None, Some(""), Some("retained cache")] {
                let id = deck.add_text_field(0, &[0], None, 0, kind, cache).unwrap();
                assert!(ids.insert(id));
            }
        }
        let body = child_at(
            &deck.slides[0].slide.common_slide_data.shape_tree.children,
            &[0],
        )
        .and_then(|owner| match owner {
            ShapeTreeChild::Shape(shape) => shape.text_body.as_ref(),
            _ => None,
        })
        .unwrap();
        let fields = body.paragraphs()[0]
            .runs
            .iter()
            .filter_map(|run| match run {
                TextRun::Field(field) => Some(field),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(fields.len(), FIELD_TYPES.len() * 3);
        assert_eq!(fields[0].text, None);
        assert_eq!(
            fields[1].text.as_ref().map(|text| text.value.as_str()),
            Some("")
        );
        assert_eq!(
            fields[2].text.as_ref().map(|text| text.value.as_str()),
            Some("retained cache")
        );
        let before = deck.to_bytes().unwrap();
        assert!(
            deck.add_text_field(0, &[0], None, 0, "unknown", None)
                .is_err()
        );
        assert!(
            deck.add_text_field(0, &[0], None, 0, "slidenum", Some("invalid\u{0}"))
                .is_err()
        );
        assert!(
            deck.add_text_field(0, &[0], None, 999, "slidenum", None)
                .is_err()
        );
        assert_eq!(deck.to_bytes().unwrap(), before);
        let reopened = Presentation::from_bytes(&before).unwrap();
        assert_eq!(
            reopened.field_identity_inventory().unwrap(),
            deck.field_identity_inventory().unwrap()
        );
    }

    #[test]
    fn fx208_transitions_preserve_retained_siblings_and_all_slide_atomicity() {
        let mut deck = Presentation::new().unwrap();
        deck.add_slide(6).unwrap();
        deck.add_slide(6).unwrap();
        let original = format!(
            r#"<q:transition xmlns:q="{P_NS}" xmlns:e="urn:fx208" e:raw='opaque' advClick="0"><q:fade/><q:sndAc><q:stSnd><q:snd name="owned sound"/></q:stSnd></q:sndAc><q:extLst><q:ext uri="opaque"><e:payload/></q:ext></q:extLst></q:transition>"#
        );
        Arc::make_mut(&mut deck.slides[0]).slide.transition =
            Some(rpptx_oxml::timing::CT_SlideTransition::from_xml(original.as_bytes()).unwrap());
        for name in TransitionKind::NAMES {
            let kind = TransitionKind::parse(name).unwrap();
            for direction in
                std::iter::once(None).chain(kind.directions().iter().copied().map(Some))
            {
                let value = SlideTransition {
                    direction,
                    kind: Some(kind.clone()),
                    duration_ms: Some(1234),
                    advance_on_click: Some(false),
                    advance_after_ms: Some(0),
                };
                deck.set_slide_transition(0, Some(&value)).unwrap();
                let raw =
                    String::from_utf8(deck.slides[0].slide.transition.as_ref().unwrap().to_xml())
                        .unwrap();
                assert!(
                    raw.contains("e:raw='opaque'")
                        && raw.contains("<q:sndAc>")
                        && raw.contains("<e:payload/>"),
                    "{raw}"
                );
                assert_eq!(deck.slide(0).unwrap().transition(), Some(value.clone()));
                let bytes = deck.to_bytes().unwrap();
                assert!(!deck.set_slide_transition(0, Some(&value)).unwrap());
                assert_eq!(deck.to_bytes().unwrap(), bytes);
                assert_eq!(
                    Presentation::from_bytes(&bytes)
                        .unwrap()
                        .slide(0)
                        .unwrap()
                        .transition(),
                    Some(value)
                );
            }
        }
        let before = deck.to_bytes().unwrap();
        let invalid = SlideTransition {
            kind: Some(TransitionKind::Fade),
            direction: Some(TransitionDirection::Left),
            ..SlideTransition::default()
        };
        assert!(deck.set_all_transitions(Some(&invalid)).is_err());
        assert_eq!(deck.to_bytes().unwrap(), before);
        let alternate = format!(
            r#"<mc:AlternateContent xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:q="{P_NS}" xmlns:e="urn:fx208"><mc:Choice Requires="e"><e:transition retained="unknown"/></mc:Choice><mc:Fallback><q:transition><q:fade/><q:sndAc/><q:extLst><q:ext uri="opaque"><e:payload/></q:ext></q:extLst></q:transition></mc:Fallback></mc:AlternateContent>"#
        );
        // Parse the valid MC wrapper through its owning slide parser.
        let slide = deck.slides[0].slide.to_xml().unwrap();
        let slide = String::from_utf8(slide).unwrap();
        let mut typed = deck.slides[0].slide.clone();
        typed.transition = None;
        let clean = String::from_utf8(typed.to_xml().unwrap()).unwrap();
        let injected = clean.replace("</p:sld>", &format!("{alternate}</p:sld>"));
        Arc::make_mut(&mut deck.slides[0]).slide = CT_Slide::from_xml(injected.as_bytes()).unwrap();
        let cover = SlideTransition {
            kind: Some(TransitionKind::Cover),
            direction: Some(TransitionDirection::RightDown),
            ..SlideTransition::default()
        };
        deck.set_slide_transition(0, Some(&cover)).unwrap();
        let retained =
            String::from_utf8(deck.slides[0].slide.transition.as_ref().unwrap().to_xml()).unwrap();
        assert!(retained.contains(
            "<mc:Choice Requires=\"e\"><e:transition retained=\"unknown\"/></mc:Choice>"
        ));
        assert!(retained.contains("<q:sndAc/>") && retained.contains("<e:payload/>"));
        assert_eq!(deck.slide(0).unwrap().transition(), Some(cover.clone()));
        let opaque = format!(
            r#"<q:transition xmlns:q="{P_NS}" xmlns:e="urn:fx208"><q:fade e:opaque='retain'/></q:transition>"#
        );
        Arc::make_mut(&mut deck.slides[1]).slide.transition =
            Some(rpptx_oxml::timing::CT_SlideTransition::from_xml(opaque.as_bytes()).unwrap());
        let before = deck.to_bytes().unwrap();
        assert!(deck.set_all_transitions(Some(&cover)).is_err());
        assert_eq!(deck.to_bytes().unwrap(), before);
        let _ = slide;
        deck.set_slide_transition(0, None).unwrap();
        assert!(deck.slide(0).unwrap().transition().is_none());
    }

    #[test]
    fn fx208_compatible_imported_date_alias_keeps_cache_and_identity() {
        let mut deck = Presentation::new().unwrap();
        deck.add_slide(1).unwrap();
        let alias = HeaderFooter {
            date: HeaderFooterDate::Automatic {
                field_type: "datetime".to_owned(),
                text: Some("retained cache".to_owned()),
            },
            ..HeaderFooter::default()
        };
        deck.set_slide_header_footer(0, &alias).unwrap();
        let before = deck.to_bytes().unwrap();
        let ids = deck.field_identity_inventory().unwrap();
        let current = HeaderFooter {
            date: HeaderFooterDate::Automatic {
                field_type: "datetime1".to_owned(),
                text: None,
            },
            ..HeaderFooter::default()
        };
        deck.set_slide_header_footer(0, &current).unwrap();
        assert!(
            matches!(deck.slide_header_footer(0).unwrap().date, HeaderFooterDate::Automatic { text: Some(ref text), .. } if text == "retained cache"),
            "compatible datetime alias must preserve its cached value"
        );
        assert_eq!(deck.field_identity_inventory().unwrap(), ids);
        assert_eq!(deck.to_bytes().unwrap(), before);
        let mut reopened = Presentation::from_bytes(&before).unwrap();
        reopened.set_header_footer(&current, false).unwrap();
        assert!(
            matches!(reopened.slide_header_footer(0).unwrap().date, HeaderFooterDate::Automatic { text: Some(ref text), .. } if text == "retained cache")
        );
    }

    #[test]
    fn fx208_missing_footer_geometry_refuses_before_publication() {
        let mut source = Presentation::new().unwrap();
        source.add_slide(1).unwrap();
        let settings = HeaderFooter {
            footer: Some("geometry control".to_owned()),
            ..HeaderFooter::default()
        };
        let mut positive = source.clone();
        positive.set_header_footer(&settings, false).unwrap();
        assert_eq!(
            positive.slide_header_footer(0).unwrap().footer.as_deref(),
            Some("geometry control")
        );
        let mut package =
            OpcPackage::from_reader(std::io::Cursor::new(source.to_bytes().unwrap())).unwrap();
        let layout_part = source.layouts[1].part_name.clone();
        let mut layout = CT_SlideLayout::from_xml(package.get_part(&layout_part).unwrap()).unwrap();
        find_latent_mut(
            &mut layout.common_slide_data.shape_tree.children,
            &PhType::Footer,
        )
        .unwrap()
        .shape_properties
        .transform = None;
        let (master_part, mut master) = source.layout_master_part(1).unwrap();
        find_latent_mut(
            &mut master.common_slide_data.shape_tree.children,
            &PhType::Footer,
        )
        .unwrap()
        .shape_properties
        .transform = None;
        package.set_part(&layout_part, layout.to_xml().unwrap());
        package.set_part(&master_part, master.to_xml().unwrap());
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        let mut deck = Presentation::from_bytes(bytes.get_ref()).unwrap();
        assert!(
            find_latent(
                &deck.layouts[1].layout.common_slide_data.shape_tree.children,
                &PhType::Footer
            )
            .unwrap()
            .shape_properties
            .transform
            .is_none()
        );
        assert!(
            find_latent(
                &deck
                    .layout_master_part(1)
                    .unwrap()
                    .1
                    .common_slide_data
                    .shape_tree
                    .children,
                &PhType::Footer
            )
            .unwrap()
            .shape_properties
            .transform
            .is_none()
        );
        let before = deck.to_bytes().unwrap();
        assert!(
            deck.set_header_footer(&settings, false).is_err(),
            "missing footer geometry must refuse before publication"
        );
        assert_eq!(deck.to_bytes().unwrap(), before);
        // Enabled legal policy with the same valid but unplaced template must
        // also refuse new-slide publication.
        layout.header_footer = Some(CT_HeaderFooter::new(
            Some(false),
            Some(false),
            Some(true),
            Some(false),
        ));
        package.set_part(&layout_part, layout.to_xml().unwrap());
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        let mut deck = Presentation::from_bytes(bytes.get_ref()).unwrap();
        let before = deck.to_bytes().unwrap();
        assert!(
            deck.add_slide(1).is_err(),
            "missing enabled footer geometry must refuse new slide"
        );
        assert_eq!(deck.to_bytes().unwrap(), before);
        for (width, height) in [(0, 1), (1, 0), (-1, 1), (1, -1)] {
            let mut transform = CT_Transform2D::from_xml(
                b"<a:xfrm xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\"><a:ext cx=\"1\" cy=\"1\"/></a:xfrm>"
            ).unwrap();
            transform.extent = Some(CT_PositiveSize2D {
                cx: Emu(width),
                cy: Emu(height),
            });
            if width < 0 || height < 0 {
                // The XML parser already rejects negative sizes. Also check
                // the typed authoring boundary before any publication.
                assert!(CT_Transform2D::from_xml(&transform.to_xml().unwrap()).is_err());
                let mut typed = source.clone();
                let layout = &mut Arc::make_mut(&mut typed.layouts[1]).layout;
                layout.header_footer = Some(CT_HeaderFooter::new(
                    Some(false),
                    Some(false),
                    Some(true),
                    Some(false),
                ));
                find_latent_mut(
                    &mut layout.common_slide_data.shape_tree.children,
                    &PhType::Footer,
                )
                .unwrap()
                .shape_properties
                .transform = Some(transform);
                let before = typed.to_bytes().unwrap();
                assert!(typed.set_header_footer(&settings, false).is_err());
                assert_eq!(typed.to_bytes().unwrap(), before);
                assert!(typed.add_slide(1).is_err());
                assert_eq!(typed.to_bytes().unwrap(), before);
                continue;
            }
            find_latent_mut(
                &mut layout.common_slide_data.shape_tree.children,
                &PhType::Footer,
            )
            .unwrap()
            .shape_properties
            .transform = Some(transform.clone());
            find_latent_mut(
                &mut master.common_slide_data.shape_tree.children,
                &PhType::Footer,
            )
            .unwrap()
            .shape_properties
            .transform = Some(transform);
            package.set_part(&layout_part, layout.to_xml().unwrap());
            package.set_part(&master_part, master.to_xml().unwrap());
            let mut bytes = std::io::Cursor::new(Vec::new());
            package.write_to(&mut bytes).unwrap();
            let mut deck = Presentation::from_bytes(bytes.get_ref()).unwrap();
            let before = deck.to_bytes().unwrap();
            assert!(
                deck.set_header_footer(&settings, false).is_err(),
                "nonpositive footer geometry {width}/{height} must refuse"
            );
            assert_eq!(deck.to_bytes().unwrap(), before);
            assert!(
                deck.add_slide(1).is_err(),
                "nonpositive new-slide footer geometry {width}/{height} must refuse"
            );
            assert_eq!(deck.to_bytes().unwrap(), before);
        }
    }

    #[cfg(feature = "render")]
    #[test]
    fn fx208_uncached_date_reports_without_computing_ambient_text() {
        let mut deck = Presentation::new().unwrap();
        deck.add_slide(6).unwrap();
        deck.slide_mut(0)
            .unwrap()
            .add_textbox(Emu(914400), Emu(914400), Emu(3657600), Emu(914400))
            .unwrap();
        deck.add_text_field(0, &[0], None, 0, "datetime1", None)
            .unwrap();
        let bytes = deck.to_bytes().unwrap();
        let (_, layout) = deck.render_deterministic().unwrap();
        assert!(
            layout
                .diagnostics
                .iter()
                .any(|value| value.message.contains("uncached automatic date")),
            "uncached automatic date must report no computed static date"
        );
        assert_eq!(deck.to_bytes().unwrap(), bytes);
        let reopened = Presentation::from_bytes(&bytes).unwrap();
        let (_, layout) = reopened.render_deterministic().unwrap();
        assert!(
            layout
                .diagnostics
                .iter()
                .any(|value| value.message.contains("uncached automatic date"))
        );
        let mut empty = Presentation::new().unwrap();
        empty.add_slide(6).unwrap();
        empty
            .slide_mut(0)
            .unwrap()
            .add_textbox(Emu(914400), Emu(914400), Emu(3657600), Emu(914400))
            .unwrap();
        empty
            .add_text_field(0, &[0], None, 0, "datetime1", Some(""))
            .unwrap();
        let (_, layout) = empty.render_deterministic().unwrap();
        assert!(
            !layout
                .diagnostics
                .iter()
                .any(|value| value.message.contains("uncached automatic date"))
        );
    }

    #[test]
    #[ignore = "requires the pinned native branded and two-master input family"]
    fn fx208_native_branded_masters_footer_and_new_slide_outputs() {
        let directory = std::path::PathBuf::from(
            std::env::var("RDOCX_FX208_NATIVE_INPUT_DIR").expect("pinned native input directory"),
        );
        let output = std::path::PathBuf::from(
            std::env::var("RDOCX_FX208_NATIVE_OUTPUT_DIR")
                .expect("isolated native output directory"),
        );
        std::fs::create_dir_all(&output).unwrap();
        let mut deck = Presentation::open(directory.join("ion-office-two-masters.pptx")).unwrap();
        assert_eq!(deck.slide_master_count(), 2);
        assert_ne!(
            deck.theme(0).unwrap().unwrap().name,
            deck.theme(1).unwrap().unwrap().name
        );
        let original_layout = deck.slide_layout_index(0).unwrap();
        let automatic = HeaderFooter {
            slide_number: true,
            footer: Some("Global footer".to_owned()),
            date: HeaderFooterDate::Automatic {
                field_type: "datetime1".to_owned(),
                text: Some("12/10/2026".to_owned()),
            },
        };
        deck.set_header_footer(&automatic, false).unwrap();
        deck.set_slide_number_start(Some(0)).unwrap();
        let bytes = deck.to_bytes().unwrap();
        deck.set_header_footer(&automatic, false).unwrap();
        assert_eq!(deck.to_bytes().unwrap(), bytes);
        std::fs::write(output.join("library-global-auto-start0.pptx"), &bytes).unwrap();
        let fixed = HeaderFooter {
            footer: Some("Selected override".to_owned()),
            date: HeaderFooterDate::Fixed("12/10/2026".to_owned()),
            ..automatic.clone()
        };
        deck.set_slide_header_footer(1, &fixed).unwrap();
        assert_eq!(deck.slide_header_footer(1), Some(fixed.clone()));
        assert_eq!(deck.slide_header_footer(0), Some(automatic.clone()));
        let bytes = deck.to_bytes().unwrap();
        let mut reopened = Presentation::from_bytes(&bytes).unwrap();
        assert_eq!(reopened.slide_header_footer(1), Some(fixed));
        std::fs::write(output.join("library-local-fixed-start0.pptx"), &bytes).unwrap();
        reopened.add_slide(original_layout).unwrap();
        assert_eq!(
            reopened.slide_header_footer(reopened.len() - 1),
            Some(automatic)
        );
        assert_eq!(reopened.slide_number_start().unwrap(), Some(0));
        assert_eq!(reopened.slide_master_count(), 2);
        let new_slide = reopened.to_bytes().unwrap();
        std::fs::write(output.join("library-new-branded-slide.pptx"), &new_slide).unwrap();
        let template = Presentation::open(directory.join("ion-office-footer-native.potx")).unwrap();
        assert_eq!(template.slide_master_count(), 2);
        let path = output.join("library-native-template.potx");
        let bytes = template.to_bytes_for_path(&path).unwrap();
        assert_eq!(
            Presentation::from_bytes(&bytes)
                .unwrap()
                .slide_header_footer(1),
            template.slide_header_footer(1)
        );
        std::fs::write(path, bytes).unwrap();
    }

    #[cfg(feature = "render")]
    #[test]
    fn fx208_displayed_start_zero_keeps_physical_pages_and_timeline_fields() {
        let mut p = Presentation::new().unwrap();
        p.add_slide(1).unwrap();
        p.add_slide(1).unwrap();
        p.set_header_footer(
            &HeaderFooter {
                slide_number: true,
                ..HeaderFooter::default()
            },
            false,
        )
        .unwrap();
        p.set_slide_number_start(Some(0)).unwrap();
        let (_, layout) = p.render_deterministic().unwrap();
        assert_eq!(
            layout
                .pages
                .iter()
                .map(|page| page.page_number)
                .collect::<Vec<_>>(),
            [1, 2]
        );
        let runs = fx210_layout_runs(&layout);
        assert!(runs.iter().any(|run| run.text == "0"));
        assert!(runs.iter().any(|run| run.text == "1"));
        let frame = p
            .render_timeline_deterministic(
                0,
                TimelinePosition {
                    elapsed_ms: 0,
                    click_count: 0,
                },
                None,
            )
            .unwrap();
        let mut texts = Vec::new();
        oxml_layout::walk(&frame.page.elements, &mut |element, _| match element {
            PositionedElement::Text(run) => texts.push(run.text.clone()),
            PositionedElement::MultilingualText(run) => texts.push(run.legacy_projection().text),
            _ => {}
        });
        assert!(
            texts.iter().any(|text| text == "0"),
            "timeline texts: {texts:?}, state: {:?}",
            frame.state
        );
        assert_eq!(frame.page.page_number, 1);
        let before = p.to_bytes().unwrap();
        assert!(p.set_slide_number_start(Some(u32::MAX)).is_err());
        assert_eq!(p.to_bytes().unwrap(), before);
        assert_eq!(
            Presentation::from_bytes(&before)
                .unwrap()
                .slide_number_start()
                .unwrap(),
            Some(0)
        );
    }

    fn presentation_with_slide() -> Presentation {
        let mut presentation = Presentation::new().unwrap();
        presentation.add_slide(0).unwrap();
        presentation
    }

    fn package_after_save(presentation: Presentation) -> OpcPackage {
        OpcPackage::from_reader(Cursor::new(presentation.to_bytes().unwrap())).unwrap()
    }

    #[test]
    fn fx206_unchanged_imported_duplicate_ids_preserve_source_and_save_invariants() {
        let valid = presentation_with_slide();
        assert!(valid.save_invariants_preserved());
        let mut package = package_after_save(valid);
        let part = "/ppt/slides/slide1.xml";
        let original = String::from_utf8(package.get_part(part).unwrap().to_vec()).unwrap();
        assert_eq!(original.matches("id=\"3\"").count(), 1);
        let duplicate = original.replacen("id=\"3\"", "id=\"2\"", 1).into_bytes();
        package.set_part(part, duplicate.clone());
        let imported = Presentation::from_package(package).unwrap();
        assert_eq!(
            imported.validate(),
            vec![ValidationIssue::DuplicateShapeId { slide: 0, id: 2 }]
        );
        assert!(imported.save_invariants_preserved());
        let bytes = imported.to_bytes().unwrap();
        assert_eq!(bytes, imported.to_bytes().unwrap());
        let saved = OpcPackage::from_reader(Cursor::new(&bytes)).unwrap();
        assert_eq!(saved.get_part(part).unwrap(), duplicate);
        let reopened = Presentation::from_bytes(&bytes).unwrap();
        assert_eq!(reopened.to_bytes().unwrap(), bytes);
        let converted = imported
            .to_bytes_as(PresentationPackageClass::Presentation)
            .unwrap();
        assert_eq!(
            OpcPackage::from_reader(Cursor::new(converted))
                .unwrap()
                .get_part(part)
                .unwrap(),
            duplicate
        );
        let path = std::env::temp_dir().join(format!(
            "fx206-duplicate-source-{}.pptx",
            std::process::id()
        ));
        imported.save(&path).unwrap();
        assert_eq!(
            OpcPackage::from_reader(Cursor::new(std::fs::read(&path).unwrap()))
                .unwrap()
                .get_part(part)
                .unwrap(),
            duplicate
        );
        std::fs::remove_file(path).unwrap();

        let mut generated = presentation_with_slide();
        Arc::make_mut(&mut generated.slides[0]).slide = imported.slides[0].slide.clone();
        assert!(
            !generated.save_invariants_preserved(),
            "new duplicate identities stay invalid"
        );
        let mut unrelated_invalid = imported.clone();
        unrelated_invalid
            .package
            .set_part("/ppt/media/orphan.png", b"orphan".to_vec());
        unrelated_invalid
            .package
            .content_types
            .add_default("png", "image/png");
        assert!(
            !unrelated_invalid.save_invariants_preserved(),
            "other invariant failures stay invalid"
        );
    }

    #[test]
    fn presentation_main_part_and_relationship_owner_resolve_case_equivalent_spelling() {
        let mut package = package_after_save(presentation_with_slide());
        let presentation_xml = package.parts.remove("/ppt/presentation.xml").unwrap();
        package
            .parts
            .insert("/PPT/PRESENTATION.XML".to_owned(), presentation_xml);
        let relationships = package.part_rels.remove("/ppt/presentation.xml").unwrap();
        package
            .part_rels
            .insert("/PPT/PRESENTATION.XML".to_owned(), relationships);

        let presentation = Presentation::from_package(package).unwrap();
        let saved = package_after_save(presentation);
        assert!(saved.parts.contains_key("/PPT/PRESENTATION.XML"));
        assert!(saved.part_rels.contains_key("/PPT/PRESENTATION.XML"));
    }

    fn presentation_from_package(package: OpcPackage) -> Presentation {
        let mut bytes = Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        Presentation::from_bytes(bytes.get_ref()).unwrap()
    }

    fn presentation_with_custom_show(relationship_id: &str) -> Presentation {
        let mut package = package_after_save(presentation_with_slide());
        let presentation_part = "/ppt/presentation.xml";
        let xml = String::from_utf8(package.get_part(presentation_part).unwrap().to_vec()).unwrap();
        let custom_show = format!(
            r#"<q:custShowLst xmlns:q="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:rel="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><q:custShow name="validation"><q:sldLst><q:sld rel:id="{relationship_id}"/></q:sldLst></q:custShow></q:custShowLst>"#
        );
        package.set_part(
            presentation_part,
            xml.replacen(
                "</p:presentation>",
                &format!("{custom_show}</p:presentation>"),
                1,
            )
            .into_bytes(),
        );
        presentation_from_package(package)
    }

    fn assert_has_issue(presentation: &Presentation, predicate: impl Fn(&ValidationIssue) -> bool) {
        let issues = presentation.validate();
        assert!(issues.iter().any(predicate), "issues: {issues:?}");
    }

    fn layout_index(presentation: &Presentation, name: &str) -> usize {
        (0..presentation.layout_count())
            .find(|index| presentation.layout_name(*index) == Some(name))
            .unwrap_or_else(|| panic!("missing layout {name}"))
    }

    #[test]
    fn three_added_slides_have_unique_ids_and_reopen() {
        let mut presentation = Presentation::new().unwrap();
        for _ in 0..3 {
            presentation.add_slide(0).unwrap();
        }

        let ids = presentation
            .slides()
            .map(|slide| slide.id())
            .collect::<HashSet<_>>();
        assert_eq!(ids.len(), 3);
        assert!(ids.iter().all(|id| *id >= 256));
        assert_eq!(
            Presentation::from_bytes(&presentation.to_bytes().unwrap())
                .unwrap()
                .len(),
            3
        );
    }

    #[test]
    fn add_slide_allocates_after_the_highest_existing_part_suffix() {
        let mut presentation = Presentation::new().unwrap();
        let sentinel = b"existing sparse slide".to_vec();
        presentation
            .package
            .set_part("/ppt/slides/slide7.xml", sentinel.clone());

        presentation.add_slide(0).unwrap();

        assert_eq!(
            presentation.slides.last().unwrap().part_name,
            "/ppt/slides/slide8.xml"
        );
        assert_eq!(
            presentation.package.get_part("/ppt/slides/slide7.xml"),
            Some(sentinel.as_slice())
        );
    }

    #[test]
    fn fx206_placeholder_names_match_all_authenticated_default_layouts() {
        let expected: &[(&str, &[&str])] = &[
            ("Title Slide", &["Title 1", "Subtitle 2"][..]),
            (
                "Title and Vertical Text",
                &["Title 1", "Vertical Text Placeholder 2"][..],
            ),
            (
                "Vertical Title and Text",
                &["Vertical Title 1", "Vertical Text Placeholder 2"][..],
            ),
            (
                "Title and Content",
                &["Title 1", "Content Placeholder 2"][..],
            ),
            ("Section Header", &["Title 1", "Text Placeholder 2"][..]),
            (
                "Two Content",
                &["Title 1", "Content Placeholder 2", "Content Placeholder 3"][..],
            ),
            (
                "Comparison",
                &[
                    "Title 1",
                    "Text Placeholder 2",
                    "Content Placeholder 3",
                    "Text Placeholder 4",
                    "Content Placeholder 5",
                ][..],
            ),
            ("Title Only", &["Title 1"][..]),
            ("Blank", &[][..]),
            (
                "Content with Caption",
                &["Title 1", "Content Placeholder 2", "Text Placeholder 3"][..],
            ),
            (
                "Picture with Caption",
                &["Title 1", "Picture Placeholder 2", "Text Placeholder 3"][..],
            ),
        ];
        for (layout_name, names) in expected {
            let mut deck = Presentation::new().unwrap();
            let index = layout_index(&deck, layout_name);
            let source_part = deck.layouts[index].part_name.clone();
            let source_xml = deck.layouts[index].layout.to_xml().unwrap();
            deck.add_slide(index).unwrap();
            let actual = deck
                .slide(0)
                .unwrap()
                .shapes()
                .map(|s| s.non_visual_name().unwrap())
                .collect::<Vec<_>>();
            assert_eq!(
                actual, *names,
                "authenticated template layout {layout_name}"
            );
            assert_eq!(deck.layouts[index].layout.to_xml().unwrap(), source_xml);
            assert_eq!(deck.layouts[index].part_name, source_part);
            let bytes = deck.to_bytes().unwrap();
            let reopened = Presentation::from_bytes(&bytes).unwrap();
            let saved = reopened
                .slide(0)
                .unwrap()
                .shapes()
                .map(|s| s.non_visual_name().unwrap())
                .collect::<Vec<_>>();
            assert_eq!(saved, actual);
            assert_eq!(reopened.to_bytes().unwrap(), bytes);
        }
    }

    #[test]
    fn fx206_placeholder_names_retain_layout_orientation_size_and_opaque_metadata() {
        let mut deck = Presentation::new().unwrap();
        let index = layout_index(&deck, "Title and Content");
        let raw = br#"<p:ph xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:f="urn:foreign" idx="1" orient="vert" sz="half" f:orient="horz" f:keep="A &amp; B"><f:payload spelling="kept&#32;exact"/></p:ph>"#;
        let replacement = CT_Placeholder::from_xml(raw).unwrap();
        let expected_ph = replacement.to_xml().unwrap();
        let child = &mut Arc::make_mut(&mut deck.layouts[index])
            .layout
            .common_slide_data
            .shape_tree
            .children[1];
        let ShapeTreeChild::Shape(shape) = child else {
            panic!("actual content placeholder");
        };
        shape.placeholder = Some(replacement);
        shape.set_name("Imported custom layout name").unwrap();
        let source_layout_part = deck.layouts[index].layout.to_xml().unwrap();
        let layout_part = deck.layouts[index].part_name.clone();
        // Import the edited layout as a real package part. The layout cache is
        // read-only through the public API and is not a layout editing facade.
        deck.package
            .set_part(&layout_part, source_layout_part.clone());
        deck = Presentation::from_package(deck.package.clone()).unwrap();
        assert_eq!(
            deck.package.get_part(&layout_part),
            Some(source_layout_part.as_slice())
        );
        let source_layout = deck.layouts[index].layout.to_xml().unwrap();
        deck.add_slide(index).unwrap();
        assert_eq!(
            deck.slide(0)
                .unwrap()
                .shape(1)
                .unwrap()
                .non_visual_name()
                .as_deref(),
            Some("Vertical Content Placeholder 2")
        );
        let ShapeTreeChild::Shape(created) =
            &deck.slides[0].slide.common_slide_data.shape_tree.children[1]
        else {
            panic!("generated content placeholder");
        };
        assert_eq!(
            created.placeholder.as_ref().unwrap().to_xml().unwrap(),
            expected_ph
        );
        assert_eq!(deck.layouts[index].layout.to_xml().unwrap(), source_layout);
        let bytes = deck.to_bytes().unwrap();
        let mut reopened = Presentation::from_bytes(&bytes).unwrap();
        let old_slide = reopened.slides[0].slide.to_xml().unwrap();
        let reopened_layout = reopened.layouts[index].layout.to_xml().unwrap();
        let ShapeTreeChild::Shape(imported) = &reopened.layouts[index]
            .layout
            .common_slide_data
            .shape_tree
            .children[1]
        else {
            panic!("reopened imported content placeholder");
        };
        assert_eq!(
            reopened.layouts[index]
                .layout
                .common_slide_data
                .shape_tree
                .children[1]
                .non_visual_name()
                .unwrap(),
            "Imported custom layout name"
        );
        assert_eq!(
            imported.placeholder.as_ref().unwrap().to_xml().unwrap(),
            expected_ph
        );
        reopened.add_slide(index).unwrap();
        assert_eq!(reopened.slides[0].slide.to_xml().unwrap(), old_slide);
        assert_eq!(
            reopened.layouts[index].layout.to_xml().unwrap(),
            reopened_layout
        );
        assert_eq!(
            reopened.package.get_part(&layout_part),
            Some(source_layout_part.as_slice())
        );
    }

    #[test]
    fn fx206_placeholder_names_cover_reference_types_vertical_and_collisions() {
        let cases = [
            (PhType::Title, "Title"),
            (PhType::CenteredTitle, "Title"),
            (PhType::Body, "Text Placeholder"),
            (PhType::Subtitle, "Subtitle"),
            (PhType::Object, "Content Placeholder"),
            (PhType::Chart, "Chart Placeholder"),
            (PhType::Table, "Table Placeholder"),
            (PhType::ClipArt, "ClipArt Placeholder"),
            (PhType::Diagram, "SmartArt Placeholder"),
            (PhType::Media, "Media Placeholder"),
            (PhType::DateTime, "Date Placeholder"),
            (PhType::Footer, "Footer Placeholder"),
            (PhType::Header, "Header Placeholder"),
            (PhType::SlideNumber, "Slide Number Placeholder"),
            (PhType::Picture, "Picture Placeholder"),
            (PhType::SlideImage, "Slide Image Placeholder"),
        ];
        for (kind, base) in cases {
            let mut tree = CT_ShapeTree::new();
            let ph = CT_Placeholder::new(Some(kind), Some(7));
            assert_eq!(
                generated_placeholder_name(&tree, &ph, 2).unwrap(),
                format!("{base} 1")
            );
            let mut existing = CT_Shape::new_placeholder(50, ph.clone()).unwrap();
            existing.set_name(&format!("{base} 1")).unwrap();
            tree.append_child(ShapeTreeChild::Shape(existing));
            assert_eq!(
                generated_placeholder_name(&tree, &ph, 2).unwrap(),
                format!("{base} 2")
            );
            assert_eq!(tree.children[0].non_visual_id(), Some(50));
            assert_eq!(
                tree.children[0].non_visual_name().as_deref(),
                Some(format!("{base} 1").as_str())
            );
        }
        let tree = CT_ShapeTree::new();
        let foreign = CT_Placeholder::from_xml(br#"<p:ph xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:f="urn:f" f:orient="vert"/>"#).unwrap();
        assert_eq!(
            generated_placeholder_name(&tree, &foreign, 2).unwrap(),
            "Content Placeholder 1"
        );
        let vertical = CT_Placeholder::from_xml(br#"<p:ph xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" orient="vert"/>"#).unwrap();
        assert_eq!(
            generated_placeholder_name(&tree, &vertical, 2).unwrap(),
            "Vertical Content Placeholder 1"
        );
        let unknown = CT_Placeholder::new(Some(PhType::Other("futureType".to_owned())), Some(8));
        assert_eq!(
            generated_placeholder_name(&tree, &unknown, 9).unwrap(),
            "Placeholder 9"
        );

        // Imported duplicate names and IDs stay in the source layout. New owners use fresh IDs.
        let mut deck = Presentation::new().unwrap();
        let index = layout_index(&deck, "Title and Content");
        for child in &mut Arc::make_mut(&mut deck.layouts[index])
            .layout
            .common_slide_data
            .shape_tree
            .children
        {
            let ShapeTreeChild::Shape(shape) = child else {
                continue;
            };
            let Some(ph) = shape.placeholder.clone() else {
                continue;
            };
            if is_latent_placeholder(&ph) {
                continue;
            }
            let mut replacement = CT_Shape::new_placeholder(50, ph).unwrap();
            replacement.set_name("Imported duplicate name").unwrap();
            *shape = replacement;
        }
        let original_layout = deck.layouts[index].layout.to_xml().unwrap();
        deck.add_slide(index).unwrap();
        let created = deck.slide(0).unwrap();
        assert_eq!(
            created
                .shapes()
                .map(|shape| shape.non_visual_id().unwrap())
                .collect::<Vec<_>>(),
            vec![2, 3]
        );
        assert_eq!(
            created
                .shapes()
                .map(|shape| shape.non_visual_name().unwrap())
                .collect::<Vec<_>>(),
            vec!["Title 1", "Content Placeholder 2"]
        );
        assert_eq!(
            deck.layouts[index].layout.to_xml().unwrap(),
            original_layout
        );
    }

