    #[test]
    fn fx206_native_cell_anchor_clear_is_lazy_and_preserves_body() {
        let mut table = CT_Table::new(1, 1, Emu(100), Emu(100)).unwrap();
        table.rows[0].cells[0].properties = None;
        let before = table.to_xml().unwrap();
        {
            let mut cell = TableCellMut {
                table: &mut table,
                row: 0,
                column: 0,
            };
            assert_eq!(cell.vertical_anchor(), None);
            cell.set_vertical_anchor(None);
        }
        assert_eq!(table.to_xml().unwrap(), before);
        assert!(table.rows[0].cells[0].properties.is_none());
        let original_body = table.rows[0].cells[0].text_body.clone().unwrap();
        for value in [
            Some(TextAnchor::Top),
            Some(TextAnchor::Center),
            Some(TextAnchor::Bottom),
            None,
        ] {
            TableCellMut {
                table: &mut table,
                row: 0,
                column: 0,
            }
            .set_vertical_anchor(value);
            assert_eq!(
                TableCellRef {
                    cell: &table.rows[0].cells[0]
                }
                .vertical_anchor(),
                value
            );
            assert_eq!(
                table.rows[0].cells[0].text_body.as_ref().unwrap(),
                &original_body
            );
            let saved = table.to_xml().unwrap();
            let reopened = CT_Table::from_xml(&saved).unwrap();
            assert_eq!(
                TableCellRef {
                    cell: &reopened.rows[0].cells[0]
                }
                .vertical_anchor(),
                value
            );
            TableCellMut {
                table: &mut table,
                row: 0,
                column: 0,
            }
            .set_vertical_anchor(value);
            assert_eq!(table.to_xml().unwrap(), saved);
        }
    }

    #[cfg(feature = "render")]
    #[test]
    fn fx206_native_picture_placeholder_fill_preserves_order_relationship_and_crop() {
        for (width, height, horizontal) in [(200, 100, true), (100, 200, false)] {
            let mut presentation = presentation_with_slide();
            let mut source =
                CT_Shape::new_placeholder(99, CT_Placeholder::new(Some(PhType::Picture), Some(4)))
                    .unwrap();
            source.shape_properties.transform = Some(positioned_transform(
                Emu(12700),
                Emu(25400),
                Emu(1270000),
                Emu(1270000),
            ));
            let index = presentation.slides[0]
                .slide
                .common_slide_data
                .shape_tree
                .children
                .len();
            Arc::make_mut(&mut presentation.slides[0])
                .slide
                .common_slide_data
                .shape_tree
                .append_child(ShapeTreeChild::Shape(source));
            let siblings = presentation.slides[0]
                .slide
                .common_slide_data
                .shape_tree
                .children[..index]
                .to_vec();
            let image = render_bound_png_header(width, height);
            let before = presentation.to_bytes().unwrap();
            assert!(
                presentation
                    .fill_picture_placeholder(0, &[index], b"bad image", "bad.png")
                    .is_err()
            );
            assert_eq!(presentation.to_bytes().unwrap(), before);
            presentation
                .fill_picture_placeholder(0, &[index], &image, "image.png")
                .unwrap();
            assert_eq!(
                presentation.slides[0]
                    .slide
                    .common_slide_data
                    .shape_tree
                    .children[..index],
                siblings
            );
            let child = &presentation.slides[0]
                .slide
                .common_slide_data
                .shape_tree
                .children[index];
            assert_eq!(child.non_visual_id(), Some(99));
            let ShapeTreeChild::Picture(picture) = child else {
                panic!("selected child must become a picture");
            };
            assert_eq!(picture.placeholder.as_ref().unwrap().idx, Some(4));
            assert!(picture.shape_properties.custom_geometry.is_none());
            assert_eq!(
                picture
                    .shape_properties
                    .preset_geometry
                    .as_ref()
                    .unwrap()
                    .preset,
                "rect"
            );
            let saved_picture = String::from_utf8(picture.to_xml().unwrap()).unwrap();
            assert_eq!(
                saved_picture.matches("<a:prstGeom prst=\"rect\">").count(),
                1
            );
            assert!(
                saved_picture.find("<a:xfrm").unwrap() < saved_picture.find("<a:prstGeom").unwrap()
            );
            let crop = picture
                .blip_fill
                .as_ref()
                .unwrap()
                .source_rect
                .as_ref()
                .unwrap();
            if horizontal {
                assert_eq!(crop.left, Some(Percent1000(25000)));
                assert_eq!(crop.right, crop.left);
                assert_eq!(crop.top, None);
            } else {
                assert_eq!(crop.top, Some(Percent1000(25000)));
                assert_eq!(crop.bottom, crop.top);
                assert_eq!(crop.left, None);
            }
            assert_eq!(presentation.picture_image(0, 99).unwrap().bytes, image);
            let saved = presentation.to_bytes().unwrap();
            let reopened = Presentation::from_bytes(&saved).unwrap();
            assert_eq!(reopened.picture_image(0, 99).unwrap().bytes, image);
            assert_eq!(
                reopened.effective_geometry(0, &[index]).unwrap(),
                Some((Emu(12700), Emu(25400), Emu(1270000), Emu(1270000)))
            );
            assert!(
                presentation
                    .fill_picture_placeholder(0, &[index], &image, "image.png")
                    .is_err()
            );
            assert_eq!(presentation.to_bytes().unwrap(), saved);
        }
    }

    #[test]
    fn add_slide_synthesizes_only_non_latent_layout_placeholders() {
        let mut presentation = Presentation::new().unwrap();
        let layout_index = layout_index(&presentation, "Title and Content");
        let expected = presentation.layouts[layout_index]
            .layout
            .common_slide_data
            .shape_tree
            .children
            .iter()
            .filter_map(|child| match child {
                ShapeTreeChild::Shape(shape) => shape.placeholder.as_ref(),
                _ => None,
            })
            .filter(|placeholder| {
                !matches!(
                    placeholder.ph_type,
                    Some(PhType::DateTime | PhType::Footer | PhType::SlideNumber)
                )
            })
            .map(|placeholder| (placeholder.ph_type.clone(), placeholder.idx))
            .collect::<Vec<_>>();

        presentation.add_slide(layout_index).unwrap();

        let actual = presentation.slides[0]
            .slide
            .common_slide_data
            .shape_tree
            .children
            .iter()
            .filter_map(|child| match child {
                ShapeTreeChild::Shape(shape) => shape.placeholder.as_ref(),
                _ => None,
            })
            .map(|placeholder| (placeholder.ph_type.clone(), placeholder.idx))
            .collect::<Vec<_>>();
        assert_eq!(actual, expected);
    }

    #[test]
    fn synthesized_slide_uses_schema_order_and_one_relative_layout_relationship() {
        let mut presentation = Presentation::new().unwrap();
        let relocated_layout = "/custom/layouts/relocated.xml";
        let original_layout = presentation.layouts[0].part_name.clone();
        let layout_xml = presentation
            .package
            .get_part(&original_layout)
            .unwrap()
            .to_vec();
        presentation.package.set_part(relocated_layout, layout_xml);
        Arc::make_mut(&mut presentation.layouts[0]).part_name = relocated_layout.to_owned();
        presentation.add_slide(0).unwrap();
        let record = &presentation.slides[0];
        let xml = String::from_utf8(record.slide.to_xml().unwrap()).unwrap();
        let relationships = presentation
            .package
            .get_part_rels(&record.part_name)
            .unwrap();

        assert!(xml.find("<p:cSld").unwrap() < xml.find("<p:clrMapOvr").unwrap());
        assert_eq!(relationships.items.len(), 1);
        assert_eq!(relationships.items[0].rel_type, rel_types::SLIDE_LAYOUT);
        assert!(!relationships.items[0].target.starts_with('/'));
        assert_eq!(
            OpcPackage::resolve_rel_target(&record.part_name, &relationships.items[0].target),
            relocated_layout
        );
        assert_eq!(CT_Slide::from_xml(xml.as_bytes()).unwrap(), record.slide);
    }

